    .cc-detail-head {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      margin-bottom: 8px;
      padding-bottom: 6px;
      border-bottom: 1px solid var(--border);
    }

    .cc-detail-title {
      font-size: 9pt;
      font-weight: 700;
      color: var(--txt-1);
      letter-spacing: 0.8px;
      text-transform: uppercase;
    }

    .cc-detail-hint {
