    .pr-stat {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 9px;
      padding: 14px 16px;
      position: relative;
      overflow: hidden;
    }

    .pr-stat::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      bottom: 0;
      width: 1px;
      border-radius: 9px 0 0 9px;
    }

    .pr-stat.c-red::before {
      background: var(--red);
    }

    .pr-stat.c-green::before {
      background: var(--green);
    }

    .pr-stat.c-blue::before {
      background: var(--blue);
    }

    .pr-stat.c-amber::before {
      background: var(--amber);
    }

    .pr-stat-label {
      font-size: 9pt;
