       PREDICTIVE ANALYSIS & RATE INTELLIGENCE
       â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• */

    /* Programme forecast strip */
    .pa-strip {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 10px;
   
    }

    @media(max-width:1100px) {
      .pa-strip {
        grid-template-columns: repeat(3, 1fr);
      }
    }

    /* ── KPI strip — matches cmdoverview card design ── */
    .pa-kpi {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 9px;
      padding: 10px;
      position: relative;
      overflow: hidden;
      display: flex;
      flex-direction: column;
      transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
    }

    .pa-kpi:hover {
      box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
    }

    /* Top accent bar — 1px */
    .pa-kpi::before {
      content: '';
      position: absolute;
      top: 0; left: 0; right: 0; bottom: auto;
      width: auto; height: 1px;
      border-radius: 9px 9px 0 0;
      opacity: 0.95;
    }

    .pa-kpi.c-green::before { background: var(--green); }
    .pa-kpi.c-amber::before { background: var(--amber); }
    .pa-kpi.c-red::before   { background: var(--red); }
    .pa-kpi.c-blue::before  { background: var(--blue); }
    .pa-kpi.c-teal::before  { background: var(--teal); }

    /* Head row: label + icon */
    .pa-kpi-head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 8px;
      margin-bottom: 10px;
    }

    .pa-kpi-label {
      font-size: 8pt;
      font-weight: 600;
      letter-spacing: 0.7px;
      text-transform: uppercase;
      color: var(--txt-muted);
      margin: 0;
      line-height: 1.2;
      flex: 1;
    }

    .pa-kpi-icon {
      width: 26px; height: 26px; flex-shrink: 0;
      border-radius: 7px;
      display: inline-flex; align-items: center; justify-content: center;
    }

    .pa-kpi-icon svg { width: 14px; height: 14px; }

    /* Icon background colors — light mode */
    .pa-kpi.c-green .pa-kpi-icon { background: rgba(0, 176, 80, 0.12);   color: var(--green); }
    .pa-kpi.c-amber .pa-kpi-icon { background: rgba(255, 192, 0, 0.14);  color: var(--amber); }
    .pa-kpi.c-red   .pa-kpi-icon { background: rgba(255, 0, 0, 0.12);    color: var(--red); }
    .pa-kpi.c-blue  .pa-kpi-icon { background: rgba(41,55,141, 0.12); color: var(--blue); }
    .pa-kpi.c-teal  .pa-kpi-icon { background: rgba(0, 176, 240, 0.12);  color: var(--teal); }

    .pa-kpi-val {
      font-size: 20pt;
      font-weight: 700;
      color: var(--txt-1);
      line-height: 1;
      font-family: var(--font-family-mono);
      margin: 0 0 6px;
    }

    .pa-kpi-val.green { color: var(--green); }
    .pa-kpi-val.red   { color: var(--red); }
    .pa-kpi-val.amber { color: var(--amber); }

    .pa-kpi-sub {
      font-size: 9pt;
      color: var(--txt-dim);
      margin-top: 0;
      line-height: 1.4;
    }

    .pa-kpi-delta {
      font-size: 9pt;
      margin-top: 4px;
      font-weight: 500;
    }

    .pa-kpi-delta.up {
      color: var(--green);
    }

    .pa-kpi-delta.dn {
      color: var(--red);
    }

    /* Rig-on alert banner */
    .pa-rig-alerts {
      display: flex;
      flex-direction: column;
      gap: 6px;
      margin-bottom: 10px;
    }

    .pa-rig-alert {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 9px 14px;
      border-radius: 7px;
      font-size: 9pt;
      border: 1px solid;
      animation: slideDown 0.3s ease;
    }

    @keyframes slideDown {
      from {
        opacity: 0;
        transform: translateY(-6px)
      }

      to {
        opacity: 1;
        transform: translateY(0)
      }
    }

    .pa-rig-alert.urgent {
      background: var(--red-soft);
      border-color: var(--red-bd);
      color: var(--red);
    }

    .pa-rig-alert.warn {
      background: var(--amber-soft);
      border-color: var(--amber-bd);
      color: var(--amber);
    }

    .pa-rig-alert svg {
      width: 14px;
      height: 14px;
      flex-shrink: 0;
    }

    .pa-rig-alert-body {
      flex: 1;
      color: var(--txt-1);
    }

    .pa-rig-alert-body strong {
      font-weight: 700;
    }

    .pa-rig-tag {
      font-size: 9pt;
      font-weight: 700;
      padding: 2px 7px;
      border-radius: 3px;
      background: var(--red);
      color: #fff;
      letter-spacing: 0.5px;
      flex-shrink: 0;
    }

    .pa-rig-tag.warn-tag {
      background: var(--amber);
    }

    /* Tabs (reuse .ai-tabs/.ai-tab pattern) */

    /* Prediction table */
    .pa-tbl {
      width: 100%;
      border-collapse: collapse;
    }

    .pa-tbl th {
      padding: 9px 12px;
      font-size: 9pt;
      font-weight: 700;
      letter-spacing: 0.6px;
      text-transform: uppercase;
      color: var(--txt-muted);
      background: var(--surface-2);
      border-bottom: 1px solid var(--border);
      text-align: left;
      white-space: nowrap;
    }

    .pa-tbl td {
      padding: 10px 12px;
      font-size: 9pt;
      border-bottom: 1px solid var(--border-2);
      vertical-align: middle;
    }

    .pa-tbl tr:last-child td {
      border-bottom: none;
    }

    .pa-tbl tr:hover td {
      background: rgba(0, 0, 0, 0.015);
    }

    .pa-tbl tr.crit td {
      background: rgba(255, 0, 0, 0.03);
    }

    /* Rate bar (inline mini bar in table) */
    .pa-rate-bar {
      display: flex;
      align-items: center;
      gap: 7px;
    }

    .pa-rate-track {
      flex: 1;
      max-width: 100px;
      height: 7px;
      background: rgba(0, 0, 0, 0.06);
      border-radius: 4px;
      overflow: visible;
      position: relative;
    }

    .pa-rate-fill {
      height: 100%;
      border-radius: 4px;
    }

    .pa-rate-ask-marker {
      position: absolute;
      top: -3px;
      height: 13px;
      width: 2px;
      background: var(--txt-1);
      border-radius: 1px;
    }

    .pa-rate-val {
      font-family: var(--font-family-mono);
      font-size: 9pt;
      font-weight: 600;
      min-width: 40px;
    }

    /* Trend spark */
    .pa-spark {
      display: inline-block;
    }

    .pa-spark svg {
      display: block;
    }

    /* Buffer indicator */
    .pa-buf {
      font-family: var(--font-family-mono);
      font-size: 9pt;
      font-weight: 700;
      white-space: nowrap;
    }

    .pa-buf.pos {
      color: var(--green);
    }

    .pa-buf.neg {
      color: var(--red);
    }

    /* Crew-add recommendation */
    .pa-crew-rec {
      display: flex;
      align-items: center;
      gap: 5px;
    }

    .pa-crew-rec-add {
      background: var(--red-soft);
      color: var(--red);
      border: 1px solid var(--red-bd);
      font-size: 9pt;
      font-weight: 700;
      padding: 2px 8px;
      border-radius: 4px;
      white-space: nowrap;
    }

    .pa-crew-rec-ok {
      background: var(--green-soft);
      color: var(--green);
      border: 1px solid var(--green-bd);
      font-size: 9pt;
      font-weight: 600;
      padding: 2px 8px;
      border-radius: 4px;
    }

    /* Cost vs penalty pill */
    .pa-cpill {
      font-size: 9pt;
      font-weight: 600;
      padding: 2px 7px;
      border-radius: 4px;
      white-space: nowrap;
    }

    .pa-cpill.save {
      background: var(--green-soft);
      color: var(--green);
      border: 1px solid var(--green-bd);
    }

    .pa-cpill.loss {
      background: var(--red-soft);
      color: var(--red);
      border: 1px solid var(--red-bd);
    }

    .pa-cpill.none {
      background: var(--surface-2);
      color: var(--txt-muted);
      border: 1px solid var(--border);
    }

    /* What-if panel */
    .pa-whatif-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 10px;
    }

    @media(max-width:900px) {
      .pa-whatif-grid {
        grid-template-columns: 1fr;
      }
    }

    .pa-wi-card {
      background: var(--surface-2);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 14px;
    }

    .pa-wi-head {
      font-size: 9pt;
      font-weight: 600;
      color: var(--txt-1);
      margin-bottom: 10px;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .pa-wi-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 5px 0;
      border-bottom: 1px solid var(--border-2);
      font-size: 9pt;
    }

    .pa-wi-row:last-child {
      border-bottom: none;
    }

    .pa-wi-label {
      color: var(--txt-2);
    }

    .pa-wi-val {
      font-family: var(--font-family-mono);
      font-weight: 700;
      color: var(--txt-1);
    }

    .pa-wi-val.green {
      color: var(--green);
    }

    .pa-wi-val.red {
      color: var(--red);
    }

    .pa-wi-val.amber {
      color: var(--amber);
    }

    .pa-wi-controls {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-top: 10px;
    }

    .pa-wi-slider {
      flex: 1;
      -webkit-appearance: none;
      height: 5px;
      border-radius: 3px;
      background: rgba(0, 0, 0, 0.1);
      cursor: pointer;
    }

    .pa-wi-slider::-webkit-slider-thumb {
      -webkit-appearance: none;
      width: 16px;
      height: 16px;
      border-radius: 50%;
      background: var(--blue);
      border: 2px solid #fff;
      box-shadow: 0 1px 4px rgba(0, 0, 0, 0.2);
    }

    .pa-wi-select {
      font-family: inherit;
      font-size: 9pt;
      padding: 5px 8px;
      border: 1px solid var(--border);
      border-radius: 6px;
      background: var(--surface);
      color: var(--txt-1);
      cursor: pointer;
    }

    .pa-wi-select:focus {
      outline: none;
      border-color: var(--accent);
    }

    .pa-scenario-result {
      margin-top: 10px;
      padding: 12px 14px;
      border-radius: 7px;
      background: var(--blue-soft);
      border: 1px solid var(--blue-bd);
      font-size: 9pt;
      color: var(--blue);
      line-height: 1.6;
    }

    .pa-scenario-result strong {
      font-weight: 700;
    }

    /* Backward schedule / Gantt */
    .pa-gantt-wrap {
      overflow-x: auto;
    }

    .pa-gantt-tbl {
      width: 100%;
      border-collapse: collapse;
      min-width: 600px;
    }

    .pa-gantt-tbl th {
      padding: 8px 12px;
      font-size: 9pt;
      font-weight: 700;
      letter-spacing: 0.6px;
      text-transform: uppercase;
      color: var(--txt-muted);
      background: var(--surface-2);
      border-bottom: 1px solid var(--border);
      text-align: left;
    }

    .pa-gantt-tbl td {
      padding: 9px 12px;
      font-size: 9pt;
      border-bottom: 1px solid var(--border-2);
      vertical-align: middle;
    }

    .pa-gantt-tbl tr:last-child td {
      border-bottom: none;
    }

    .pa-gantt-bar-wrap {
      position: relative;
      height: 20px;
      background: rgba(0, 0, 0, 0.04);
      border-radius: 4px;
      overflow: hidden;
    }

    .pa-gantt-bar {
      height: 100%;
      border-radius: 4px;
      position: absolute;
      display: flex;
      align-items: center;
      padding: 0 6px;
      font-size: 9pt;
      font-weight: 700;
      color: #fff;
      white-space: nowrap;
      overflow: hidden;
    }

    .pa-gantt-today {
      position: absolute;
      top: 0;
      bottom: 0;
      width: 2px;
      background: var(--red);
      opacity: 0.8;
    }

    .pa-latest-start {
      font-family: var(--font-family-mono);
      font-size: 9pt;
      font-weight: 700;
    }

    .pa-late-warn {
      color: var(--red);
    }

    .pa-on-time {
      color: var(--green);
    }

    /* Programme-level forecast */
    .pa-prog-row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 10px;
    }

    @media(max-width:900px) {
      .pa-prog-row {
        grid-template-columns: 1fr;
      }
    }

    .pa-conf-badge {
      font-size: 9pt;
      font-weight: 700;
      padding: 2px 8px;
      border-radius: 4px;
      background: var(--blue-soft);
      color: var(--blue);
      border: 1px solid var(--blue-bd);
    }

    /* â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
       LABOUR PRODUCTIVITY INTELLIGENCE
       â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• */

    /* Offline sync bar */
    .lp-sync-bar {
      display: flex;
      align-items: center;
      gap: 10px;
      padding:14px;
      background: #fffbeb;
      border: 1px solid #fde047;
      border-radius: 7px;
      font-size: 9pt;
      margin-bottom: 10px;
    }

    .lp-sync-bar svg {
      width: 14px;
      height: 14px;
      color: #ca8a04;
      flex-shrink: 0;
    }

    .lp-sync-btn {
      margin-left: auto;
      padding: 4px 12px;
      background: #ca8a04;
      color: #fff;
      border: none;
      border-radius: 5px;
      font-size: 9pt;
      font-weight: 600;
      cursor: pointer;
      font-family: inherit;
      transition: background 0.15s;
    }

    .lp-sync-btn:hover {
      background: #a16207;
    }

    .lp-sync-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      flex-shrink: 0;
    }

    .lp-sync-dot.pending {
      background: #FFC000;
      box-shadow: 0 0 6px rgba(255, 192, 0, 0.5);
      animation: aiPulse 2s infinite;
    }

    .lp-sync-dot.synced {
      background: #00B050;
    }

    /* KPI strip */
    .lp-strip {
      display: grid;
      grid-template-columns: repeat(6, 1fr);
      gap: 10px;
      margin-bottom: 10px;
    }

    @media(max-width:1200px) {
      .lp-strip {
        grid-template-columns: repeat(3, 1fr);
      }
    }

    /* ── KPI strip — matches cmdoverview card design ── */
    .lp-kpi {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 9px;
      padding: 10px;
      position: relative;
      overflow: hidden;
      display: flex;
      flex-direction: column;
      cursor: default;
      transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
    }

    .lp-kpi:hover {
      box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
    }

    /* Top accent bar — 1px */
    .lp-kpi::before {
      content: '';
      position: absolute;
      top: 0; left: 0; right: 0; bottom: auto;
      width: auto; height: 1px;
      border-radius: 9px 9px 0 0;
      opacity: 0.95;
    }

    .lp-kpi.c-green::before  { background: var(--green); }
    .lp-kpi.c-blue::before   { background: var(--blue); }
    .lp-kpi.c-amber::before  { background: var(--amber); }
    .lp-kpi.c-red::before    { background: var(--red); }
    .lp-kpi.c-teal::before   { background: var(--teal); }
    .lp-kpi.c-purple::before { background: #29378d; }

    /* Head row: label + icon */
    .lp-kpi-head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 8px;
      margin-bottom: 10px;
    }

    .lp-kpi-label {
      font-size: 8pt;
      font-weight: 600;
      letter-spacing: 0.7px;
      text-transform: uppercase;
      color: var(--txt-muted);
      margin: 0;
      line-height: 1.2;
      flex: 1;
    }

    .lp-kpi-icon {
      width: 26px; height: 26px; flex-shrink: 0;
      border-radius: 7px;
      display: inline-flex; align-items: center; justify-content: center;
    }

    .lp-kpi-icon svg { width: 14px; height: 14px; }

    /* Icon background colors — light mode */
    .lp-kpi.c-green  .lp-kpi-icon { background: rgba(0, 176, 80, 0.12);    color: var(--green); }
    .lp-kpi.c-blue   .lp-kpi-icon { background: rgba(41,55,141, 0.12);  color: var(--blue); }
    .lp-kpi.c-amber  .lp-kpi-icon { background: rgba(255, 192, 0, 0.14);   color: var(--amber); }
    .lp-kpi.c-red    .lp-kpi-icon { background: rgba(255, 0, 0, 0.12);     color: var(--red); }
    .lp-kpi.c-teal   .lp-kpi-icon { background: rgba(0, 176, 240, 0.12);   color: var(--teal); }
    .lp-kpi.c-purple .lp-kpi-icon { background: rgba(41,55,141, 0.12);  color: #29378d; }

    .lp-kpi-val {
      font-size: 20pt;
      font-weight: 700;
      color: var(--txt-1);
      line-height: 1;
      font-family: var(--font-family-mono);
      margin: 0 0 6px;
    }

    .lp-kpi-val.green  { color: var(--green); }
    .lp-kpi-val.red    { color: var(--red); }
    .lp-kpi-val.amber  { color: var(--amber); }
    .lp-kpi-val.purple { color: #29378d; }

    .lp-kpi-sub {
      font-size: 9pt;
      color: var(--txt-dim);
      margin-top: 0;
      line-height: 1.4;
    }

    /* Anomaly badge */
    .lp-anomaly {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      font-size: 9pt;
      font-weight: 700;
      padding: 2px 7px;
      border-radius: 4px;
      letter-spacing: 0.4px;
    }

    .lp-anomaly.critical {
      background: rgba(255, 0, 0, 0.1);
      color: #FF0000;
      border: 1px solid rgba(255, 0, 0, 0.25);
    }

    .lp-anomaly.warn {
      background: rgba(255, 192, 0, 0.1);
      color: #FFC000;
      border: 1px solid rgba(255, 192, 0, 0.25);
    }

    .lp-anomaly.info {
      background: var(--blue-soft);
      color: var(--blue);
      border: 1px solid var(--blue-bd);
    }

    .lp-anomaly.none {
      background: var(--green-soft);
      color: var(--green);
      border: 1px solid var(--green-bd);
    }

    /* P-rating achievement bar */
    .lp-ach-wrap {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .lp-ach-track {
      flex: 1;
      max-width: 120px;
      height: 8px;
      background: rgba(0, 0, 0, 0.06);
      border-radius: 4px;
      overflow: hidden;
      position: relative;
    }

    .lp-ach-fill {
      height: 100%;
      border-radius: 4px;
      transition: width 0.4s;
    }

    .lp-ach-val {
      font-family: var(--font-family-mono);
      font-size: 9pt;
      font-weight: 700;
      min-width: 38px;
    }

    /* Attendance grid */
    .lp-att-grid {
      display: grid;
      gap: 6px;
      grid-template-columns: 120px repeat(7, 1fr);
    }

    .lp-att-head {
      font-size: 9pt;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      color: var(--txt-muted);
      padding: 4px 6px;
      text-align: center;
    }

    .lp-att-row-label {
      font-family: var(--font-family-mono);
      font-size: 9pt;
      font-weight: 500;
      color: var(--txt-1);
      padding: 4px 0;
      display: flex;
      align-items: center;
    }

    .lp-att-cell {
      height: 32px;
      border-radius: 5px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 9pt;
      font-weight: 700;
      transition: all 0.15s;
      cursor: default;
    }

    .lp-att-cell.present {
      background: rgba(22, 163, 74, 0.15);
      color: var(--green);
    }

    .lp-att-cell.absent {
      background: rgba(255, 0, 0, 0.1);
      color: var(--red);
    }

    .lp-att-cell.partial {
      background: rgba(255, 192, 0, 0.12);
      color: var(--amber);
    }

    .lp-att-cell.na {
      background: rgba(0, 0, 0, 0.03);
      color: var(--txt-muted);
    }

    /* Idle time cause chips */
    .lp-idle-chip {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      padding: 3px 8px;
      border-radius: 12px;
      font-size: 9pt;
      font-weight: 600;
      margin: 2px;
      background: var(--surface-2);
      border: 1px solid var(--border);
      color: var(--txt-2);
    }

    .lp-idle-chip .dot {
      width: 6px;
      height: 6px;
      border-radius: 50%;
      flex-shrink: 0;
    }

    /* Photo evidence grid */
    .lp-photo-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
      gap: 10px;
    }

    .lp-photo-card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 9px;
      overflow: hidden;
      transition: box-shadow 0.15s;
    }

    .lp-photo-card:hover {
      box-shadow: 0 4px 14px rgba(0, 0, 0, 0.1);
    }

    .lp-photo-thumb {
      height: 130px;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }

    .lp-photo-meta {
      padding: 10px 12px;
    }

    .lp-photo-id {
      font-family: var(--font-family-mono);
      font-size: 9pt;
      font-weight: 600;
      color: var(--txt-1);
    }

    .lp-photo-detail {
      font-size: 9pt;
      color: var(--txt-muted);
      margin-top: 3px;
      line-height: 1.4;
    }

    .lp-gps-badge {
      position: absolute;
      bottom: 6px;
      right: 6px;
      background: rgba(22, 163, 74, 0.9);
      color: #fff;
      font-size: 9pt;
      font-weight: 700;
      padding: 2px 7px;
      border-radius: 10px;
      display: flex;
      align-items: center;
      gap: 3px;
    }

    .lp-gps-badge svg {
      width: 9px;
      height: 9px;
    }

    .lp-unverified {
      background: rgba(255, 192, 0, 0.85);
    }

    /* Field capture form */
    .lp-form-card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 14px;
      margin-bottom: 10px;
    }

    .lp-form-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 10px;
      margin-bottom: 10px;
    }

    @media(max-width:900px) {
      .lp-form-grid {
        grid-template-columns: repeat(2, 1fr);
      }
    }

    .lp-form-field label {
      display: block;
      font-size: 9pt;
      font-weight: 600;
      color: var(--txt-muted);
      letter-spacing: 0.5px;
      text-transform: uppercase;
      margin-bottom: 4px;
    }

    .lp-form-field input,
    .lp-form-field select,
    .lp-form-field textarea {
      width: 100%;
      padding: 8px 10px;
      font-family: inherit;
      font-size: 9pt;
      color: var(--txt-1);
      background: var(--surface-2);
      border: 1px solid var(--border);
      border-radius: 7px;
      transition: border 0.15s;
    }

    .lp-form-field input:focus,
    .lp-form-field select:focus {
      outline: none;
      border-color: var(--accent);
      box-shadow: 0 0 0 3px rgba(58, 111, 216, 0.08);
    }

    .lp-idle-form-row {
      display: flex;
      gap: 8px;
      align-items: center;
      margin-bottom: 6px;
    }

    .lp-idle-add-btn {
      padding: 5px 12px;
      font-size: 9pt;
      font-weight: 600;
      background: var(--surface-2);
      border: 1px dashed var(--border);
      border-radius: 6px;
      cursor: pointer;
      color: var(--txt-2);
      font-family: inherit;
      transition: all 0.15s;
    }

    .lp-idle-add-btn:hover {
      background: var(--blue-soft);
      color: var(--blue);
      border-color: var(--blue-bd);
    }

    .lp-submit-row {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-top: 12px;
      padding-top: 12px;
      border-top: 1px solid var(--border);
    }

    .lp-offline-indicator {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 9pt;
      color: var(--amber);
      font-weight: 500;
    }

    .lp-offline-indicator svg {
      width: 13px;
      height: 13px;
    }

    .lp-submit-btn {
      padding: 9px 20px;
      background: var(--blue);
      color: #fff;
      border: none;
      border-radius: 8px;
      font-size: 9pt;
      font-weight: 700;
      cursor: pointer;
      font-family: inherit;
      transition: all 0.15s;
    }

    .lp-submit-btn:hover {
      background: #29378d;
    }

    .lp-submit-btn.success {
      background: var(--green);
    }

    /* Tables */
    .lp-tbl {
      width: 100%;
      border-collapse: collapse;
    }

    .lp-tbl th {
      padding: 9px 12px;
      font-size: 9pt;
      font-weight: 700;
      letter-spacing: 0.6px;
      text-transform: uppercase;
      color: var(--txt-muted);
      background: var(--surface-2);
      border-bottom: 1px solid var(--border);
      text-align: left;
      white-space: nowrap;
    }

    .lp-tbl td {
      padding: 10px 12px;
      font-size: 9pt;
      border-bottom: 1px solid var(--border-2);
      vertical-align: middle;
    }

    .lp-tbl tr:last-child td {
      border-bottom: none;
    }

    .lp-tbl tr:hover td {
      background: rgba(0, 0, 0, 0.015);
    }

    .lp-tbl tr.flagged td {
      background: rgba(255, 0, 0, 0.03);
    }

    .lp-tbl tr.flagged:hover td {
      background: rgba(255, 0, 0, 0.06);
    }

    /* Idle donut legend */
    .lp-legend-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 5px 0;
      border-bottom: 1px solid var(--border-2);
      font-size: 9pt;
    }

    .lp-legend-row:last-child {
      border-bottom: none;
    }

    .lp-legend-dot {
      width: 11px;
      height: 11px;
      border-radius: 3px;
      flex-shrink: 0;
      margin-right: 8px;
    }

    /* Productive vs non-productive hours bar */
    .lp-time-bar {
      display: flex;
      height: 18px;
      border-radius: 5px;
      overflow: hidden;
      border: 1px solid var(--border);
    }

    .lp-time-seg {
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 9pt;
      font-weight: 700;
      color: #fff;
      transition: all 0.3s;
    }

