      height: 28px;
      display: flex;
      align-items: center;
      justify-content: center;
      background: var(--surface-2);
      border: 1px solid var(--border);
      border-radius: 6px;
      cursor: pointer;
    }

    .dq-icon-btn svg {
      width: 13px;
      height: 13px;
      color: var(--txt-2);
    }

    .dq-lang-btn {
      display: flex;
      align-items: center;
      gap: 4px;
      padding: 5px 10px;
      background: var(--surface-2);
      border: 1px solid var(--border);
      border-radius: 6px;
      font-size: 9pt;
      color: var(--txt-2);
      cursor: pointer;
    }

    /* Breadcrumb */
    .dq-breadcrumb {
      display: flex;
      align-items: center;
      gap: 6px;
      padding: 12px 0 10px;
      font-size: 9pt;
      color: var(--txt-muted);
      flex-wrap: wrap;
    }

    .dq-breadcrumb a {
      color: var(--txt-muted);
      cursor: pointer;
      text-decoration: none;
    }

    .dq-breadcrumb a:hover {
      color: var(--txt-1);
    }

    .dq-breadcrumb .sep {
      color: var(--border);
    }

    .dq-breadcrumb .cur {
      color: var(--txt-1);
      font-weight: 600;
    }

    .dq-breadcrumb .active-badge {
      background: rgba(0, 176, 80, 0.12);
      color: #00B050;
      border: 1px solid rgba(0, 176, 80, 0.3);
      font-size: 9pt;
      font-weight: 700;
      padding: 2px 9px;
      border-radius: 10px;
    }

    /* Title row */
    .dq-title {
      font-size: 14pt;
      font-weight: 700;
      color: var(--txt-1);
      letter-spacing: -0.3px;
    }

    .dq-subtitle {
      font-size: 9pt;
      color: var(--txt-muted);
      margin-top: 3px;
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .dq-subtitle .live-dot {
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: #00B050;
      box-shadow: 0 0 6px rgba(0, 176, 80, 0.5);
    }

    /* Action buttons row */
    .dq-actions {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .dq-btn {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 8px 16px;
      font-family: inherit;
      font-size: 9pt;
      font-weight: 600;
      border-radius: 8px;
      cursor: pointer;
      transition: all 0.15s;
      border: 1px solid var(--border);
    }

    .dq-btn svg {
      width: 13px;
      height: 13px;
    }

    .dq-btn-outline {
      background: var(--surface);
      color: var(--txt-2);
    }

    .dq-btn-outline:hover {
      background: var(--surface-2);
      color: var(--txt-1);
    }

    .dq-btn-blue {
      background:#29378d;
      color: #fff;
      border-color:#29378d;
;
      box-shadow: none;
    }

    .dq-btn-blue:hover {
      background:#29378d;
      box-shadow: none;
    }

    .dq-btn-ghost {
      background: transparent;
      color: var(--txt-2);
      border-color: var(--border);
    }

    .dq-sla-select {
      padding: 8px 12px;
      font-family: inherit;
      font-size: 9pt;
      font-weight: 600;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 8px;
      color: var(--txt-1);
      cursor: pointer;
    }

    /* Tab strip */
    .dq-tabs {
display: flex;
  align-items: center;
gap:10px;
  margin-bottom: 10px;
  background: var(--surface);
  border: 1px solid var(--border);
  padding: 14px;
  border-radius: 10px;
    }

    .dq-tab {
      display: inline-flex;
      align-items: center;
      gap: 7px;
      padding: 9px 18px;
      font-family: inherit;
      font-size: 9pt;
      font-weight: 500;
      border-radius: 8px;
      cursor: pointer;
      border: 1px solid transparent;
      transition: all 0.15s;
      color: var(--txt-2);
      background: transparent;
    }

    .dq-tab:hover {
      background: var(--surface-2);
      color: var(--txt-1);
    }

    .dq-tab.active {
      background: #29378d;
      border-color: transparent;
      color: #fff;
      font-weight: 700;
    }

    .dq-tab svg {
      width: 13px;
      height: 13px;
    }

    .dq-tab-body {
      background: transparent;
      border: none;
      padding:0px;
      margin-bottom: 0;
    }

    /* KPI cards */
    .dq-kpi-strip {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 10px;
      margin-bottom: 10px;
    }

    @media(max-width:1100px) {
      .dq-kpi-strip {
        grid-template-columns: repeat(3, 1fr);
      }
    }

    .dq-kpi-card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 9px;
      padding: 10px;
      position: relative;
      overflow: hidden;
      display: flex;
      flex-direction: column;
      transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
    }
    .dq-kpi-card::before {
      content: '';
      position: absolute;
      top: 0; left: 0; right: 0; bottom: auto;
      width: auto; height: 1px;
      border-radius: 9px 9px 0 0;
      opacity: 0.95;
    }
    .dq-kpi-card:hover {
      box-shadow: 0 4px 16px rgba(0,0,0,0.08);
    }
    .dq-kpi-card.red::before    { background: var(--red); }
    .dq-kpi-card.orange::before { background: #E65100; }
    .dq-kpi-card.amber::before  { background: var(--amber); }
    .dq-kpi-card.blue::before   { background: var(--blue); }
    .dq-kpi-card.green::before  { background: var(--green); }
    .dq-kpi-card.cyan::before   { background: #00B0F0; }

    .dq-kpi-head {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      margin-bottom: 10px;
    }
    .dq-kpi-label {
      font-size: 8pt;
      font-weight: 600;
      letter-spacing: 0.7px;
      text-transform: uppercase;
      color: var(--txt-muted);
      flex: 1;
      margin: 0;
      line-height: 1.3;
    }
    .dq-kpi-icon {
      width: 26px; height: 26px;
      min-width: 26px;
      border-radius: 7px;
      display: flex; align-items: center; justify-content: center;
    }
    .dq-kpi-icon svg { width: 14px; height: 14px; }
    .dq-kpi-icon--red    { background: rgba(255,0,0,0.12);    color: var(--red); }
    .dq-kpi-icon--orange { background: rgba(230,81,0,0.12);   color: #E65100; }
    .dq-kpi-icon--amber  { background: rgba(255,192,0,0.12);  color: var(--amber); }
    .dq-kpi-icon--blue   { background: rgba(41,55,141,0.12); color: var(--blue); }
    .dq-kpi-icon--green  { background: rgba(0,176,80,0.12);   color: var(--green); }
    .dq-kpi-icon--cyan   { background: rgba(0,176,240,0.12);  color: #00B0F0; }

    .dq-kpi-val {
      font-size: 20pt;
      font-weight: 700;
      line-height: 1;
      font-family: var(--font-family-mono);
      margin: 0 0 6px;
    }
    .dq-kpi-val.red    { color: var(--red); }
    .dq-kpi-val.orange { color: #E65100; }
    .dq-kpi-val.amber  { color: var(--amber); }
    .dq-kpi-val.cyan   { color: #00B0F0; }
    .dq-kpi-val.green  { color: var(--green); }

    .dq-kpi-sub {
      font-size: 9pt;
      color: var(--txt-dim);
      margin-top: 0;
      line-height: 1.4;
    }

    /* Analytics 3-panel row */
    .dq-analytics-row {
      display: grid;
      grid-template-columns: 1fr 1fr 1.1fr;
      gap: 10px;
      margin-bottom: 10px;
    }

    @media(max-width:1000px) {
      .dq-analytics-row {
        grid-template-columns: 1fr;
      }
    }

    .dq-analytics-card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 14px;
    }

    .dq-analytics-title {
      font-size: 9pt;
      font-weight: 700;
      letter-spacing: 0.6px;
      text-transform: uppercase;
      color: var(--txt-1);
      margin-bottom: 2px;
    }

    .dq-analytics-sub {
      font-size: 9pt;
      color: var(--txt-muted);
      margin-bottom: 12px;
    }

    /* Error type bars */
    .dq-type-row {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 6px 0;
    }

    .dq-type-icon {
      width: 24px;
      height: 24px;
      border-radius: 5px;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }

    .dq-type-icon svg {
      width: 12px;
      height: 12px;
    }

    .dq-type-name {
      font-size: 9pt;
      color: var(--txt-2);
      min-width: 80px;
    }

    .dq-type-bar-wrap {
      flex: 1;
      height: 7px;
      background: rgba(0, 0, 0, 0.06);
      border-radius: 4px;
      overflow: hidden;
    }

    .dq-type-bar {
      height: 100%;
      border-radius: 4px;
    }

    .dq-type-count {
      font-family: var(--font-family-mono);
      font-size: 9pt;
      font-weight: 700;
      color: var(--txt-1);
      min-width: 18px;
      text-align: right;
    }

    .dq-type-pct {
      font-size: 9pt;
      color: var(--txt-muted);
      min-width: 32px;
      text-align: right;
    }

    .dq-type-pills {
      display: flex;
      gap: 6px;
      flex-wrap: wrap;
      margin-top: 10px;
    }

    .dq-type-pill {
      font-size: 9pt;
      font-weight: 700;
      padding: 2px 9px;
      border-radius: 4px;
    }

    /* Per-well bars */
    .dq-well-scroll {
      max-height: 320px;
      overflow-y: auto;
      padding-right: 4px;
    }
    .dq-well-row {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 4px 0;
    }

    .dq-well-id {
      font-family: var(--font-family-mono);
      font-size: 9pt;
      color: var(--txt-2);
      min-width: 80px;
      max-width: 120px;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
      cursor: pointer;
    }

    .dq-well-id:hover {
      color: var(--blue);
    }

    .dq-well-bar-wrap {
      flex: 1;
      height: 10px;
      background: rgba(0, 0, 0, 0.05);
      border-radius: 5px;
      overflow: hidden;
    }

    .dq-well-bar {
      height: 100%;
      border-radius: 5px;
      transition: width 0.4s;
    }

    .dq-well-count {
      font-family: var(--font-family-mono);
      font-size: 9pt;
      font-weight: 700;
      color: var(--txt-1);
      min-width: 16px;
      text-align: right;
    }

    /* SLA countdown badges */
    .dq-sla-overdue {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      background: var(--red);
      color: #fff;
      font-size: 9pt;
      font-weight: 700;
      padding: 3px 9px;
      border-radius: 5px;
      white-space: nowrap;
    }

    .dq-sla-ok {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      background: rgba(0, 176, 80, 0.12);
      color: var(--green);
      border: 1px solid rgba(0, 176, 80, 0.3);
      font-size: 9pt;
      font-weight: 700;
      padding: 3px 9px;
      border-radius: 5px;
      white-space: nowrap;
    }

    .dq-sla-warn {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      background: var(--amber-soft);
      color: var(--amber);
      border: 1px solid var(--amber-bd);
      font-size: 9pt;
      font-weight: 700;
      padding: 3px 9px;
      border-radius: 5px;
      white-space: nowrap;
    }

    /* Error table */
    .dq-errors-header {
      display: flex;
      align-items: center;
      gap: 10px;
      flex-wrap: wrap;
      margin-bottom: 12px;
    }

    .dq-errors-title {
      font-size: 10pt;
      font-weight: 700;
      color: var(--txt-1);
      text-transform: uppercase;
      letter-spacing: .06em;
    }

    .dq-errors-title span {
      font-size: 9pt;
      font-weight: 400;
      color: var(--txt-muted);
      margin-left: 5px;
    }

    .dq-filter-row {
      display: flex;
      gap: 7px;
      align-items: center;
      flex-wrap: wrap;
    }

    .dq-search-box {
      position: relative;
    }

    .dq-search-box input {
      padding: 7px 10px 7px 30px;
      font-family: inherit;
      font-size: 9pt;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 7px;
      color: var(--txt-1);
      min-width: 180px;
    }

    .dq-search-box input:focus {
      outline: none;
      border-color: var(--accent);
    }

    .dq-search-box svg {
      position: absolute;
      left: 9px;
      top: 50%;
      transform: translateY(-50%);
      width: 13px;
      height: 13px;
      color: var(--txt-muted);
    }

    .dq-filter-sel {
      padding: 7px 10px;
      font-family: inherit;
      font-size: 9pt;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 7px;
      color: var(--txt-1);
      cursor: pointer;
    }

    .dq-ai-btn {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 7px 14px;
      background: #29378d;
      color: #fff;
      border: none;
      border-radius: 7px;
      font-size: 9pt;
      font-weight: 700;
      cursor: pointer;
      font-family: inherit;
    }

    .dq-ai-btn svg {
      width: 13px;
      height: 13px;
    }

    .dq-err-tbl {
      width: 100%;
      border-collapse: collapse;
    }

    .dq-err-tbl th {
      padding: 9px 12px;
      font-size: 9pt;
      font-weight: 700;
      letter-spacing: 0.7px;
      text-transform: uppercase;
      color: var(--txt-muted);
      background: var(--surface-2);
      border-bottom: 1px solid var(--border);
      text-align: left;
      white-space: nowrap;
    }

    .dq-err-tbl td {
      padding: 0;
      vertical-align: top;
      border-bottom: 1px solid var(--border-2);
    }

    .dq-err-tbl tr:last-child td {
      border-bottom: none;
    }

    .dq-err-cell {
      padding: 12px 12px;
    }

    .dq-sev-badge {
      display: inline-flex;
      flex-direction: column;
      align-items: center;
      gap: 2px;
    }

    .dq-sev-pill {
      font-size: 9pt;
      font-weight: 800;
      padding: 3px 8px;
      border-radius: 4px;
      letter-spacing: 0.5px;
      text-transform: uppercase;
    }

    .dq-sev-pill.critical {
      background: var(--red);
      color: #fff;
    }

    .dq-sev-pill.warning {
      background: var(--amber);
      color: #fff;
    }

    .dq-sev-pill.info {
      background: var(--blue);
      color: #fff;
    }

    .dq-sev-type {
      font-size: 9pt;
      color: var(--txt-muted);
      margin-top: 2px;
      font-style: italic;
    }

    .dq-rule-name {
      font-size: 9pt;
      font-weight: 600;
      color: var(--blue);
      margin-bottom: 2px;
    }

    .dq-rule-desc {
      font-size: 9pt;
      color: var(--txt-muted);
      margin-bottom: 5px;
    }

    .dq-field-tag {
      display: inline-block;
      font-family: var(--font-family-mono);
      font-size: 9pt;
      font-weight: 600;
      padding: 1px 7px;
      border-radius: 3px;
      background: rgba(41,55,141, 0.1);
      color: var(--blue);
      border: 1px solid rgba(41,55,141, 0.2);
      margin: 1px;
    }

    /* AI Explanation box */
    .dq-ai-box {
      background: rgba(41,55,141, 0.04);
      border: 1px solid rgba(41,55,141, 0.15);
      border-radius: 7px;
      padding: 10px 12px;
      margin: 2px 0;
    }

    .dq-ai-by {
      display: flex;
      align-items: center;
      gap: 5px;
      font-size: 9pt;
      font-weight: 700;
      color: var(--blue);
      margin-bottom: 7px;
    }

    .dq-ai-by svg {
      width: 12px;
      height: 12px;
    }

    .dq-ai-check {
      width: 16px;
      height: 16px;
      border-radius: 50%;
      background: var(--green);
      color: #fff;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      font-size: 9pt;
      font-weight: 800;
      flex-shrink: 0;
    }

    .dq-ai-main {
      font-size: 9pt;
      font-weight: 600;
      color: var(--txt-1);
      line-height: 1.5;
      margin-bottom: 6px;
    }

    .dq-ai-bullet {
      font-size: 9pt;
      color: var(--txt-2);
      line-height: 1.5;
      padding-left: 12px;
      position: relative;
    }

    .dq-ai-bullet::before {
      content: 'â€¢';
      position: absolute;
      left: 2px;
    }

    .dq-res-select {
      padding: 6px 8px;
      font-family: inherit;
      font-size: 9pt;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 6px;
      color: var(--txt-1);
      min-width: 120px;
      cursor: pointer;
    }

    .dq-eta-input,
    .dq-val-input {
      padding: 6px 8px;
      font-family: inherit;
      font-size: 9pt;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 6px;
      color: var(--txt-1);
      width: 100%;
    }

    .dq-status-sel {
      padding: 6px 8px;
      font-family: inherit;
      font-size: 9pt;
      border-radius: 6px;
      cursor: pointer;
      font-weight: 600;
      border: 1px solid;
    }

    .dq-status-sel.open {
      background: rgba(255, 0, 0, 0.08);
      color: var(--red);
      border-color: rgba(255, 0, 0, 0.25);
    }

    .dq-status-sel.progress {
      background: var(--amber-soft);
      color: var(--amber);
      border-color: var(--amber-bd);
    }

    .dq-status-sel.closed {
      background: var(--green-soft);
      color: var(--green);
      border-color: var(--green-bd);
    }

    .dq-mark-btn {
      width: 100%;
      padding: 5px 0;
      background: var(--green-soft);
      color: var(--green);
      border: 1px solid var(--green-bd);
      border-radius: 5px;
      font-size: 9pt;
      font-weight: 700;
      cursor: pointer;
      font-family: inherit;
      margin-top: 5px;
    }

    .dq-mark-btn:hover {
      background: var(--green);
      color: #fff;
    }

    /* Bottom charts row */
    .dq-bottom-row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 10px;
      margin-bottom: 10px;
    }

    .dq-bottom-row-2 {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 10px;
    }

    @media(max-width:900px) {

      .dq-bottom-row,
      .dq-bottom-row-2 {
        grid-template-columns: 1fr;
      }
    }

    .dq-chart-card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 14px;
    }

    .dq-chart-title {
      font-size: 9pt;
      font-weight: 700;
      letter-spacing: 0.6px;
      text-transform: uppercase;
      color: var(--txt-1);
      margin-bottom: 2px;
    }

    .dq-chart-sub {
      font-size: 9pt;
      color: var(--txt-muted);
      margin-bottom: 12px;
    }

    .dq-sla-big {
      font-size: 22pt;
      font-weight: 800;
      color: var(--amber);
      font-family: var(--font-family-mono);
      float: right;
      line-height: 1;
    }

    /* Resolution donut legend */
    .dq-res-legend {
      display: flex;
      flex-direction: column;
      gap: 0;
      flex: 1;
      min-width: 0;
      justify-content: center;
      border-left: 1px solid var(--border);
      padding-left: 20px;
    }

    .dq-res-row {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 10px 0;
      border-bottom: 1px solid var(--border);
    }
    .dq-res-row:last-child {
      border-bottom: none;
    }

    .dq-res-dot {
      width: 12px;
      height: 12px;
      border-radius: 2px;
      flex-shrink: 0;
    }

    .dq-res-label {
      font-size: 10pt;
      color: var(--txt-2);
      min-width: 80px;
      font-weight: 500;
    }

    .dq-res-bar-wrap {
      flex: 1;
      height: 4px;
      background: rgba(0, 0, 0, 0.06);
      border-radius: 3px;
      overflow: hidden;
    }

    .dq-res-bar {
      height: 100%;
      border-radius: 3px;
    }

    .dq-res-pct {
      font-family: var(--font-family-mono);
      font-size: 10pt;
      font-weight: 700;
      color: var(--txt-1);
      min-width: 80px;
      text-align: right;
    }

    /* Data completeness bars */
    .dq-comp-row {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 5px 0;
    }

    .dq-comp-name {
      font-size: 9pt;
      color: var(--txt-2);
      min-width: 130px;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .dq-comp-bar-wrap {
      flex: 1;
      height: 9px;
      background: rgba(0, 0, 0, 0.06);
      border-radius: 5px;
      overflow: hidden;
    }

