    /* POC banner */
    .pi-poc-banner {
      display: flex;
      align-items: flex-start;
      gap: 12px;
      padding: 12px 16px;
      background: linear-gradient(135deg, rgba(41,55,141, 0.06), rgba(13, 148, 136, 0.06));
      border: 1px solid rgba(41,55,141, 0.18);
      border-radius: 9px;
      margin-bottom: 14px;
      font-size: 9pt;
      line-height: 1.6;
    }

    .pi-poc-banner svg {
      width: 18px;
      height: 18px;
      flex-shrink: 0;
      color: var(--blue);
      margin-top: 1px;
    }

    .pi-poc-banner strong {
      color: var(--blue);
    }

    .pi-poc-tagline {
      font-size: 9pt;
      color: var(--txt-muted);
      margin-top: 3px;
      font-style: italic;
    }

    /* Hero header card */
    .pi-hero {
      background: linear-gradient(135deg, #1a3160 0%, #0f2040 100%);
      border-radius: 10px;
      padding: 18px 22px;
      color: #fff;
      display: flex;
      align-items: center;
      gap: 18px;
      margin-bottom: 14px;
      position: relative;
      overflow: hidden;
    }

    .pi-hero::before {
      content: '';
      position: absolute;
      top: -50px;
      right: -50px;
      width: 180px;
      height: 180px;
      border-radius: 50%;
      background: radial-gradient(circle, rgba(245, 200, 66, 0.15) 0%, transparent 70%);
    }

    .pi-hero-icon {
      width: 46px;
      height: 46px;
      border-radius: 10px;
      background: rgba(245, 200, 66, 0.15);
      border: 1px solid rgba(245, 200, 66, 0.3);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }

    .pi-hero-icon svg {
      width: 22px;
      height: 22px;
      stroke: #FFC000;
    }

    .pi-hero-title {
      font-size: 14pt;
      font-weight: 700;
      margin-bottom: 3px;
    }

    .pi-hero-sub {
      font-size: 9pt;
      color: rgba(255, 255, 255, 0.6);
      line-height: 1.5;
    }

    .pi-hero-stats {
      display: flex;
      gap: 22px;
      margin-top: 10px;
    }

    .pi-hero-stat .v {
      font-size: 20pt;
      font-weight: 700;
      font-family: var(--font-family-mono);
    }

    .pi-hero-stat .l {
      font-size: 9pt;
      color: rgba(255, 255, 255, 0.5);
      letter-spacing: 0.4px;
    }

    .pi-hero-stat .v.warn {
      color: #FFC000;
    }

    .pi-hero-stat .v.red {
      color: #FF0000;
    }

    .pi-hero-stat .v.green {
      color: #00B050;
    }

    /* KPI strip â€” 6 */
    .pi-strip {
      display: grid;
      grid-template-columns: repeat(6, 1fr);
      gap: 10px;
      margin-bottom: 14px;
    }

    @media(max-width:1200px) {
      .pi-strip {
        grid-template-columns: repeat(3, 1fr);
      }
    }

    .pi-kpi {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 9px;
      padding: 12px 14px;
      border-left: 3px solid var(--border);
    }

    .pi-kpi.gold {
      border-left-color: #FFC000;
    }

    .pi-kpi.red {
      border-left-color: var(--red);
    }

    .pi-kpi.green {
      border-left-color: var(--green);
    }

    .pi-kpi.blue {
      border-left-color: var(--blue);
    }

    .pi-kpi.amber {
      border-left-color: var(--amber);
    }

    .pi-kpi.purple {
      border-left-color: #1F3864;
    }

    .pi-kpi-label {
      font-size: 9pt;
      font-weight: 600;
      letter-spacing: 0.7px;
      text-transform: uppercase;
      color: var(--txt-muted);
      margin-bottom: 5px;
    }

    .pi-kpi-val {
      font-size: 20pt;
      font-weight: 800;
      line-height: 1;
      font-family: var(--font-family-mono);
    }

    .pi-kpi-val.gold {
      color: #FFC000;
    }

    .pi-kpi-val.red {
      color: var(--red);
    }

    .pi-kpi-val.green {
      color: var(--green);
    }

    .pi-kpi-val.blue {
      color: var(--blue);
    }

    .pi-kpi-val.amber {
      color: var(--amber);
    }

    .pi-kpi-val.purple {
      color: #1F3864;
    }

    .pi-kpi-sub {
      font-size: 9pt;
      color: var(--txt-muted);
      margin-top: 5px;
    }

    .pi-kpi-delta {
      font-size: 9pt;
      font-weight: 600;
      margin-top: 3px;
    }

    .pi-kpi-delta.up {
      color: var(--red);
    }

    /* higher incentive = bad in fraud context */
    .pi-kpi-delta.dn {
      color: var(--green);
    }

    /* Anomaly alert strip */
    .pi-alert-strip {
      display: flex;
      flex-direction: column;
      gap: 6px;
      margin-bottom: 14px;
    }

    .pi-alert {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 9px 14px;
      border-radius: 7px;
      font-size: 9pt;
      border: 1px solid;
    }

    .pi-alert.critical {
      background: rgba(255, 0, 0, 0.05);
      border-color: rgba(255, 0, 0, 0.2);
    }

    .pi-alert.warning {
      background: rgba(255, 192, 0, 0.05);
      border-color: rgba(255, 192, 0, 0.2);
    }

    .pi-alert svg {
      width: 14px;
      height: 14px;
      flex-shrink: 0;
    }

    .pi-alert.critical svg {
      color: var(--red);
    }

    .pi-alert.warning svg {
      color: var(--amber);
    }

    .pi-alert-body {
      flex: 1;
      color: var(--txt-1);
      line-height: 1.5;
    }

    .pi-alert-body strong {
      font-weight: 700;
    }

    .pi-alert-flag {
      font-size: 9pt;
      font-weight: 700;
      padding: 2px 8px;
      border-radius: 3px;
      letter-spacing: 0.5px;
      color: #fff;
      flex-shrink: 0;
    }

    .pi-alert-flag.critical {
      background: var(--red);
    }

    .pi-alert-flag.warning {
      background: var(--amber);
    }

    .pi-alert-est {
      font-size: 9pt;
      font-weight: 700;
      color: var(--red);
      margin-left: 4px;
    }

    /* Inflation severity badge */
    .pi-inf-badge {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      font-size: 9pt;
      font-weight: 700;
      padding: 2px 8px;
      border-radius: 4px;
    }

    .pi-inf-badge.critical {
      background: rgba(255, 0, 0, 0.1);
      color: var(--red);
      border: 1px solid rgba(255, 0, 0, 0.25);
    }

    .pi-inf-badge.warning {
      background: rgba(255, 192, 0, 0.1);
      color: var(--amber);
      border: 1px solid rgba(255, 192, 0, 0.25);
    }

    .pi-inf-badge.info {
      background: var(--blue-soft);
      color: var(--blue);
      border: 1px solid var(--blue-bd);
    }

    .pi-inf-badge.clean {
      background: var(--green-soft);
      color: var(--green);
      border: 1px solid var(--green-bd);
    }

    /* Inflation bar (rate vs norm visual) */
    .pi-rate-compare {
      display: flex;
      flex-direction: column;
      gap: 3px;
    }

    .pi-rate-bar-row {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 9pt;
    }

    .pi-rate-track {
      flex: 1;
      max-width: 90px;
      height: 6px;
      background: rgba(0, 0, 0, 0.06);
      border-radius: 3px;
      overflow: hidden;
      position: relative;
    }

    .pi-rate-fill {
      height: 100%;
      border-radius: 3px;
      transition: width 0.3s;
    }

    .pi-rate-norm-line {
      position: absolute;
      top: -1px;
      height: 8px;
      width: 2px;
      background: var(--txt-1);
      opacity: 0.4;
      border-radius: 1px;
    }

    /* Incentive cost table */
    .pi-tbl {
      width: 100%;
      border-collapse: collapse;
    }

    .pi-tbl th {
      padding: 9px 12px;
      font-size: 9pt;
      font-weight: 700;
      letter-spacing: 0.6px;
      text-transform: uppercase;
      color: var(--txt-muted);
      background: var(--surface-2);
      border-bottom: 1px solid var(--border);
      text-align: left;
      white-space: nowrap;
    }

    .pi-tbl td {
      padding: 10px 12px;
      font-size: 9pt;
      border-bottom: 1px solid var(--border-2);
      vertical-align: middle;
    }

    .pi-tbl tr:last-child td {
      border-bottom: none;
    }

    .pi-tbl tr:hover td {
      background: rgba(255, 255, 255, 0.02);
    }

    .pi-tbl tr.flagged td {
      background: rgba(255, 0, 0, 0.025);
    }

    /* Tracker layout */
    .pi-tracker-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 12px;
      margin-bottom: 14px;
    }

    @media(max-width:900px) {
      .pi-tracker-grid {
        grid-template-columns: 1fr;
      }
    }

    /* Rank bar (in tracker table) */
    .pi-rank-bar-wrap {
      flex: 1;
      max-width: 100px;
      height: 6px;
      background: rgba(0, 0, 0, 0.06);
      border-radius: 3px;
      overflow: hidden;
      display: inline-block;
      margin-right: 6px;
      vertical-align: middle;
    }

    .pi-rank-bar {
      height: 100%;
      border-radius: 3px;
      background: var(--blue);
    }

    /* AG Grid overrides â€” Incentive Intelligence dark */
    .pi-ag-grid.ag-theme-alpine-dark {
      --ag-background-color: #112448;
      --ag-header-background-color: #0d1c3a;
      --ag-odd-row-background-color: rgba(255, 255, 255, 0.02);
      --ag-row-hover-color: rgba(255, 255, 255, 0.04);
      --ag-border-color: rgba(255, 255, 255, 0.08);
      --ag-header-foreground-color: rgba(200, 215, 240, 0.55);
      --ag-foreground-color: #e8ecf5;
      --ag-secondary-foreground-color: rgba(200, 215, 240, 0.5);
      --ag-row-border-color: rgba(255, 255, 255, 0.04);
      --ag-selected-row-background-color: rgba(59, 130, 246, 0.10);
