    .pi-ag-grid.ag-theme-alpine {
      --ag-background-color: #ffffff;
      --ag-header-background-color: #f8fafc;
      --ag-odd-row-background-color: #fafbfc;
      --ag-row-hover-color: rgba(41,55,141, 0.05);
      --ag-border-color: #e2e8f0;
      --ag-header-foreground-color: #7F7F7F;
      --ag-foreground-color: #1e293b;
      --ag-secondary-foreground-color: #7F7F7F;
      --ag-row-border-color: #f1f5f9;
      --ag-selected-row-background-color: rgba(41,55,141, 0.08);
      --ag-range-selection-background-color: rgba(41,55,141, 0.06);
      --ag-font-family: var(--font-family);
      --ag-font-size: 9pt;
      --ag-grid-size: 6px;
      --ag-cell-horizontal-padding: 12px;
