    }

    .pi-ag-grid.ag-theme-alpine .ag-paging-panel {
      color: #7F7F7F;
      font-size: 9pt;
    }

    /* Correlation scatter note box */
    .pi-insight-box {
      background: linear-gradient(135deg, rgba(41,55,141, 0.05), rgba(13, 148, 136, 0.05));
      border: 1px solid rgba(41,55,141, 0.15);
      border-radius: 8px;
      padding: 14px 16px;
      margin-bottom: 12px;
    }

    .pi-insight-title {
      font-size: 9pt;
      font-weight: 700;
      color: var(--blue);
      margin-bottom: 6px;
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .pi-insight-body {
      font-size: 9pt;
      color: var(--txt-1);
      line-height: 1.6;
    }

    .pi-insight-body .highlight {
      font-weight: 700;
      color: var(--red);
    }

    .pi-insight-body .positive {
      font-weight: 700;
      color: var(--green);
    }

    /* Anomaly type chips */
    .pi-anom-IMPOSSIBLE_RATE {
      background: rgba(255, 0, 0, 0.1);
      color: #FF0000;
      border: 1px solid rgba(255, 0, 0, 0.3);
    }

    .pi-anom-SEQUENTIAL_INFLATE {
      background: rgba(255, 0, 0, 0.1);
      color: #FF0000;
      border: 1px solid rgba(255, 0, 0, 0.3);
    }

    .pi-anom-HEADCOUNT_MISMATCH {
      background: rgba(255, 192, 0, 0.1);
      color: #FFC000;
      border: 1px solid rgba(255, 192, 0, 0.3);
    }

    .pi-anom-PATTERN_ANOMALY {
      background: rgba(255, 192, 0, 0.1);
      color: #FFC000;
      border: 1px solid rgba(255, 192, 0, 0.3);
    }

    .pi-anom-DUPLICATE_ENTRY {
      background: var(--blue-soft);
