    }

    /* Problem strip */
    .pi2-problem-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 12px;
      margin-bottom: 14px;
    }

    @media(max-width:900px) {
      .pi2-problem-grid {
        grid-template-columns: 1fr;
      }
    }

    /* Inflation fact boxes */
    .pi2-fact-row {
      display: flex;
      gap: 10px;
      margin-bottom: 14px;
      flex-wrap: wrap;
    }

    .pi2-fact {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 12px 16px;
      flex: 1;
      min-width: 140px;
      border-left: 3px solid;
    }

    .pi2-fact.bad {
      border-left-color: var(--red);
    }

    .pi2-fact.warn {
      border-left-color: var(--amber);
    }

    .pi2-fact.good {
      border-left-color: var(--green);
    }

    .pi2-fact-label {
      font-size: 9pt;
      font-weight: 600;
      letter-spacing: 0.6px;
      text-transform: uppercase;
      color: var(--txt-muted);
      margin-bottom: 5px;
    }

    .pi2-fact-val {
      font-size: 22px;
      font-weight: 800;
      font-family: var(--font-family-mono);
      line-height: 1;
    }

    .pi2-fact-val.red {
      color: var(--red);
    }

    .pi2-fact-val.amber {
      color: var(--amber);
    }

    .pi2-fact-val.green {
      color: var(--green);
    }

    .pi2-fact-sub {
      font-size: 9pt;
      color: var(--txt-muted);
      margin-top: 4px;
    }

    /* 4 Module cards (scoring engine) */
    .pi2-module-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 10px;
