        grid-template-columns: repeat(2, 1fr);
      }
    }

    .pi2-module {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 9px;
      padding: 14px 16px;
    }

    .pi2-module.hse {
      border-top: 3px solid #FF0000;
    }

    .pi2-module.qual {
      border-top: 3px solid #29378d;
    }

    .pi2-module.prod {
      border-top: 3px solid #00B050;
    }

    .pi2-module.hr {
      border-top: 3px solid #29378d;
    }

    .pi2-module-head {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-bottom: 10px;
