    .pi2-module-icon {
      width: 28px;
      height: 28px;
      border-radius: 7px;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }

    .pi2-module-icon svg {
      width: 14px;
      height: 14px;
    }

    .pi2-module-name {
      font-size: 9pt;
      font-weight: 700;
      color: var(--txt-1);
      flex: 1;
