    .pi2-ag-grid.ag-theme-alpine .ag-header-cell-label {
      font-size: 9pt;
      font-weight: 700;
      letter-spacing: .5px;
      text-transform: uppercase;
    }

    .pi2-ag-grid.ag-theme-alpine .ag-row-pinned {
      background: #f1f5f9 !important;
      font-weight: 800;
    }

    .pi2-module-mini {
      display: inline-flex;
      flex-direction: column;
      align-items: center;
      gap: 2px;
      min-width: 32px;
    }

    .pi2-module-mini .lbl {
      font-size: 8.5px;
      color: var(--txt-muted);
      text-transform: uppercase;
      letter-spacing: 0.3px;
    }

    .pi2-module-mini .val {
      font-size: 9pt;
      font-weight: 700;
      font-family: var(--font-family-mono);
    }

    /* Supervisor view */
    .pi2-sup-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
      gap: 12px;
      margin-bottom: 14px;
    }

    .pi2-sup-card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 9px;
      padding: 14px 16px;
    }

    .pi2-sup-card.auto-p0 {
      border-color: rgba(255, 0, 0, 0.4);
      background: rgba(255, 0, 0, 0.025);
    }

    .pi2-sup-card-head {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-bottom: 10px;
    }

    .pi2-sup-name {
      font-size: 13px;
      font-weight: 700;
      color: var(--txt-1);
      flex: 1;
    }

    .pi2-sup-sub {
      font-size: 9pt;
      color: var(--txt-muted);
      margin-top: 1px;
    }

    .pi2-sup-module-bars {
      display: flex;
      flex-direction: column;
      gap: 6px;
      margin-top: 8px;
    }

    .pi2-sup-mod-row {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 9pt;
    }

    .pi2-sup-mod-lbl {
      min-width: 70px;
      color: var(--txt-2);
    }

    .pi2-sup-mod-track {
      flex: 1;
      height: 6px;
      background: rgba(0, 0, 0, 0.06);
      border-radius: 3px;
      overflow: hidden;
    }

    .pi2-sup-mod-fill {
      height: 100%;
      border-radius: 3px;
    }

    .pi2-sup-mod-pct {
      font-family: var(--font-family-mono);
      font-size: 9pt;
      font-weight: 700;
      min-width: 28px;
      text-align: right;
    }

    /* Approval workflow mockup */
    .pi2-workflow-notice {
      background: linear-gradient(135deg, rgba(124, 58, 237, 0.06), rgba(41,55,141, 0.06));
      border: 1px solid rgba(124, 58, 237, 0.2);
      border-radius: 8px;
      padding: 14px 18px;
      margin-bottom: 14px;
      display: flex;
      gap: 12px;
      font-size: 9pt;
      color: var(--txt-1);
      line-height: 1.6;
    }

    .pi2-workflow-notice svg {
      width: 18px;
      height: 18px;
      color: #29378d;
      flex-shrink: 0;
      margin-top: 1px;
    }

    .pi2-approval-pipeline {
      display: flex;
      align-items: stretch;
      gap: 0;
      margin-bottom: 16px;
      overflow-x: auto;
    }

    .pi2-approval-stage {
      flex: 1;
      min-width: 160px;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 0;
      padding: 14px 16px;
      position: relative;
    }

    .pi2-approval-stage:first-child {
      border-radius: 8px 0 0 8px;
    }

    .pi2-approval-stage:last-child {
      border-radius: 0 8px 8px 0;
    }

    .pi2-approval-stage+.pi2-approval-stage {
      border-left: none;
    }

    .pi2-approval-stage.active {
      background: rgba(41,55,141, 0.05);
      border-color: rgba(41,55,141, 0.3);
    }

    .pi2-stage-num {
      font-size: 9pt;
      font-weight: 700;
      color: var(--txt-muted);
      text-transform: uppercase;
      letter-spacing: 0.5px;
      margin-bottom: 4px;
    }

    .pi2-stage-title {
      font-size: 9pt;
      font-weight: 700;
      color: var(--txt-1);
      margin-bottom: 2px;
    }

    .pi2-stage-role {
      font-size: 9pt;
      color: var(--txt-muted);
      margin-bottom: 8px;
    }

    .pi2-stage-arrow {
      position: absolute;
      right: -11px;
      top: 50%;
      transform: translateY(-50%);
      width: 22px;
      height: 22px;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 1;
    }

    .pi2-stage-arrow svg {
      width: 10px;
      height: 10px;
      color: var(--txt-muted);
    }

    .pi2-approval-item {
      background: var(--surface-2);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 10px 14px;
      margin-bottom: 8px;
      opacity: 0.7;
    }

    .pi2-approval-item.pending {
      opacity: 1;
    }

    .pi2-approval-item-head {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-bottom: 6px;
    }

    .pi2-pending-pill {
      font-size: 9pt;
      font-weight: 700;
      padding: 2px 8px;
      border-radius: 10px;
      background: var(--amber-soft);
      color: var(--amber);
      border: 1px solid var(--amber-bd);
    }

    .pi2-approval-btns {
      display: flex;
      gap: 6px;
    }

    .pi2-appr-btn {
      padding: 4px 10px;
      font-family: inherit;
      font-size: 9pt;
      font-weight: 700;
      border-radius: 5px;
      cursor: pointer;
    }

    .pi2-appr-btn.approve {
      background: var(--green-soft);
      color: var(--green);
      border: 1px solid var(--green-bd);
    }

    .pi2-appr-btn.reject {
      background: var(--red-soft);
      color: var(--red);
      border: 1px solid var(--red-bd);
    }

    .pi2-appr-btn.view {
      background: var(--blue-soft);
      color: var(--blue);
      border: 1px solid var(--blue-bd);
    }

    .pi2-phase1-overlay {
      position: absolute;
      inset: 0;
      border-radius: 8px;
      background: rgba(248, 249, 251, 0.85);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      text-align: center;
      padding: 10px;
      z-index: 5;
    }

    .pi2-phase1-pill {
      background: #29378d;
      color: #fff;
      font-size: 9pt;
      font-weight: 800;
      padding: 3px 10px;
      border-radius: 10px;
      margin-bottom: 6px;
    }

    .pi2-phase1-text {
      font-size: 9pt;
      color: var(--txt-2);
      line-height: 1.4;
    }

    /* â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
       ALL WELLS PAGE
       â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• */

    /* Wells Summary KPI strip */
    .aw-summary-strip {
      display: none;
      grid-template-columns: repeat(6, 1fr);
      gap: 10px;
      margin-bottom: 10px;
    }

    @media(max-width:1280px) {
      .aw-summary-strip {
        grid-template-columns: repeat(6, 1fr);
        gap: 6px;
      }

      .aw-summary-strip .aw-kpi {
        padding: 11px 12px;
      }

      .aw-summary-strip .aw-kpi-val {
        font-size: 22px !important;
      }

      .aw-summary-strip .aw-kpi-label {
        font-size: 9pt !important;
      }

      .aw-summary-strip .aw-kpi-sub {
        font-size: 9pt !important;
      }
    }

    @media(max-width:900px) {
      .aw-summary-strip {
        grid-template-columns: repeat(3, 1fr);
      }
    }

    .aw-kpi {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 9px;
      padding: 10px;
      display: flex;
      flex-direction: column;
      position: relative;
      overflow: hidden;
      transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
    }

    .aw-kpi:hover {
      box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
    }

    .aw-kpi::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      bottom: auto;
      width: auto;
      height: 1px;
      border-radius: 9px 9px 0 0;
      opacity: 0.95;
    }

    .aw-kpi.total::before {
      background: var(--blue);
    }

    .aw-kpi.progress::before {
      background: var(--teal);
    }

    .aw-kpi.complete::before {
      background: var(--green);
    }

    .aw-kpi.early::before {
      background: #29378d;
    }

    .aw-kpi.planned::before {
      background: #7F7F7F;
    }

    .aw-kpi.critical::before {
      background: #FF0000;
    }

    .aw-kpi-label {
      font-size: 9pt;
      font-weight: 600;
      letter-spacing: 0.7px;
      text-transform: uppercase;
      color: var(--txt-muted);
      margin-bottom: 10px;
      line-height: 1.2;
    }

    .aw-kpi-val {
      font-size: 20pt;
      font-weight: 700;
      font-family: var(--font-family-mono);
      line-height: 1;
      letter-spacing: -0.5px;
      margin: 2px 0 12px;
    }

    .aw-kpi-val.blue {
      color: var(--blue);
    }

    .aw-kpi-val.teal {
      color: var(--teal);
    }

    .aw-kpi-val.green {
      color: var(--green);
    }

    .aw-kpi-val.yellow {
      color: #FFC000;
    }

    .aw-kpi-val.red {
      color: var(--red);
    }

    .aw-kpi-bar {
      height: 6px;
      border-radius: 4px;
      margin: 8px 0 8px;
    }

    .aw-kpi-pct {
      font-size: 10pt;
      font-weight: 700;
      font-family: var(--font-family-mono);
    }

    .aw-kpi-sub {
      font-size: 9pt;
      color: var(--txt-muted);
      margin-top: 4px;
    }

    /* View toggle */
    .aw-view-toggle {
      display: flex;
      gap: 4px;
    }

    .aw-view-btn {
      display: flex;
      align-items: center;
      gap: 5px;
      padding: 7px 14px;
      font-family: inherit;
      font-size: 9pt;
      font-weight: 600;
      border: 1px solid var(--border);
      border-radius: 7px;
      cursor: pointer;
      transition: all 0.15s;
      background: var(--surface);
      color: var(--txt-2);
    }

    .aw-view-btn svg {
      width: 12px;
      height: 12px;
    }

    .aw-view-btn.active {
      background: #29378d;
      color: #fff;
      border-color: #29378d;
    }

    /* Filter pill row */
    .aw-filter-row {
      display: flex;
      align-items: center;
      gap: 6px;
      flex-wrap: nowrap;
      overflow-x: auto;
      scrollbar-width: none;
      margin-bottom: 10px;
      background: var(--surface);
  border: 1px solid var(--border);
  padding: 14px;
  border-radius: 10px;
    }

    .aw-filter-icon {
      color: var(--txt-muted);
      flex-shrink: 0;
    }

    .aw-filter-icon svg {
      width: 13px;
      height: 13px;
    }

    .aw-status-pill {
      display: inline-flex;
      align-items: center;
      gap: 5px;
      padding: 5px 12px;
      border: 1px solid var(--border);
      border-radius: 10px;
      font-size: 9pt;
      font-weight: 500;
      cursor: pointer;
      transition: all 0.15s;
      background: var(--surface);
      color: var(--txt-2);
      font-family: inherit;
      white-space: nowrap;
    }

    .aw-status-pill::before {
      content: '';
      width: 7px;
      height: 7px;
      border-radius: 50%;
      flex-shrink: 0;
    }

    .aw-status-pill.all::before {
      background: var(--blue);
    }

    .aw-status-pill.activewells {
      background: rgba(79, 70, 229, 0.08);
      color: #4F46E5;
      border: 1px solid rgba(79, 70, 229, 0.35);
      font-weight: 700;
    }

    .aw-status-pill.activewells::before {
      background: #4F46E5;
    }

    .aw-status-pill.activewells.active {
      background: #4F46E5;
      color: #fff;
      border-color: #4F46E5;
    }

    .aw-status-pill.activewells.active::before {
      background: #fff;
    }

    .aw-status-pill.inprogress::before {
      background: var(--teal);
    }

    .aw-status-pill.completed::before {
      background: var(--green);
    }

    .aw-status-pill.early::before {
      background: #29378d;
    }

    .aw-status-pill.planned::before {
      background: #7F7F7F;
    }

    .aw-status-pill.onhold::before {
      background: var(--red);
    }

    .aw-status-pill.highperf::before,
    .aw-status-pill.critical::before,
    .aw-status-pill.bonuspotential::before {
      display: none;
    }

    .aw-status-pill.bonuspotential {
      color: var(--green);
      border-color: rgba(0, 176, 80, 0.35);
    }

    .aw-status-pill.bonuspotential svg {
      stroke: var(--green);
    }

    .aw-status-pill.active {
      background: var(--blue);
      color: #fff;
      border-color: var(--blue);
      font-weight: 700;
    }

    .aw-status-pill.active::before {
      background: #fff;
    }

    .aw-search-wrap {
      position: relative;
    }

    .aw-search-wrap input {
      padding: 7px 10px 7px 30px;
      font-family: inherit;
      font-size: 9pt;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 7px;
      color: var(--txt-1);
      min-width: 200px;
    }

    .aw-search-wrap input:focus {
      outline: none;
      border-color: var(--accent);
    }

    .aw-search-wrap svg {
      position: absolute;
      left: 9px;
      top: 50%;
      transform: translateY(-50%);
      width: 13px;
      height: 13px;
      color: var(--txt-muted);
      pointer-events: none;
    }

    /* Grid section header */
    .aw-grid-header {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-bottom: 10px;
    }

    .aw-grid-title {
      font-size: 9pt;
      font-weight: 700;
      letter-spacing: 0.7px;
      text-transform: uppercase;
      color: var(--txt-muted);
    }

    .aw-records-badge {
      background: var(--blue-soft);
      color: var(--blue);
      border: 1px solid var(--blue-bd);
      font-size: 9pt;
      font-weight: 700;
      padding: 2px 9px;
      border-radius: 10px;
      font-family: var(--font-family-mono);
    }

    .aw-grid-hint {
      font-size: 9pt;
      color: var(--txt-muted);
      margin-left: auto;
    }

    /* Wells data table */
    .aw-tbl {
      width: 100%;
      border-collapse: collapse;
      font-size: 9pt;
    }

    .aw-tbl thead tr {
      background: var(--surface-2);
    }

    .aw-tbl th {
      padding: 9px 10px;
      font-size: 9pt;
      font-weight: 700;
      letter-spacing: 0.7px;
      text-transform: uppercase;
      color: var(--txt-muted);
      border-bottom: 2px solid var(--border);
      white-space: nowrap;
      cursor: pointer;
      user-select: none;
    }

    .aw-tbl th:hover {
      color: var(--txt-1);
    }

    .aw-tbl td {
      padding: 10px 10px;
      border-bottom: 1px solid var(--border-2);
      vertical-align: middle;
      white-space: nowrap;
    }

    .aw-tbl tr:hover td {
      background: rgba(0, 0, 0, 0.012);
    }

    .aw-tbl tr:last-child td {
      border-bottom: none;
    }

    /* Well name link */
    .aw-well-name {
      font-family: var(--font-family-mono);
      font-size: 9pt;
      font-weight: 700;
      color: var(--blue);
      cursor: pointer;
    }

    .aw-well-name:hover {
      text-decoration: underline;
    }

    /* Status badge */
    .aw-status {
      display: inline-flex;
      align-items: center;
      gap: 5px;
      font-size: 9pt;
      font-weight: 700;
      padding: 3px 9px;
      border-radius: 10px;
      white-space: nowrap;
    }

    .aw-status::before {
      content: '';
      width: 6px;
      height: 6px;
      border-radius: 50%;
      flex-shrink: 0;
    }

    .aw-status.completed {
      background: rgba(22, 163, 74, 0.1);
      color: var(--green);
      border: 1px solid rgba(22, 163, 74, 0.25);
    }

    .aw-status.completed::before {
      background: var(--green);
    }

    .aw-status.inprogress {
      background: rgba(0, 176, 240, 0.1);
      color: var(--teal);
      border: 1px solid rgba(0, 176, 240, 0.25);
    }

    .aw-status.inprogress::before {
      background: var(--teal);
    }

    .aw-status.planned {
      background: rgba(127, 127, 127, 0.1);
      color: #7F7F7F;
      border: 1px solid rgba(127, 127, 127, 0.25);
    }

    .aw-status.planned::before {
      background: #7F7F7F;
    }

    .aw-status.onhold {
      background: rgba(255, 0, 0, 0.1);
      color: var(--red);
      border: 1px solid rgba(255, 0, 0, 0.25);
    }

    .aw-status.onhold::before {
      background: var(--red);
    }

    .aw-status.early {
      background: rgba(41,55,141, 0.1);
      color: #29378d;
      border: 1px solid rgba(41,55,141, 0.25);
    }

    .aw-status.early::before {
      background: #29378d;
