    }

    .kcd-timer.atrisk {
      color: var(--amber);
    }

    .kcd-timer.ontrack {
      color: var(--blue);
    }

    .kcd-timer.bonus {
      color: var(--green);
    }

    .kcd-timer.overdue {
      color: var(--red);
    }

    .kcd-timer-units {
      display: flex;
      gap: 6px;
      margin-bottom: 8px;
    }

    .kcd-timer-unit {
      text-align: center;
    }

    .kcd-timer-unit .digits {
      font-family: var(--font-family-mono);
      font-size: 20pt;
      font-weight: 800;
      line-height: 1;
    }

    .kcd-timer-unit .unit-lbl {
      font-size: 8.5px;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      color: var(--txt-muted);
      font-weight: 600;
    }

    .kcd-timer-sep {
      font-size: 20pt;
      font-weight: 800;
      color: var(--txt-muted);
      line-height: 1;
      align-self: flex-start;
      padding-top: 1px;
    }

    /* Progress bar */
    .kcd-prog-row {
      display: flex;
      align-items: center;
      gap: 6px;
      margin-bottom: 6px;
    }

    .kcd-prog-track {
      flex: 1;
      height: 6px;
      background: rgba(0, 0, 0, 0.07);
      border-radius: 3px;
      overflow: hidden;
    }

    .kcd-prog-fill {
      height: 100%;
      border-radius: 3px;
      transition: width 0.5s;
    }

    .kcd-prog-pct {
      font-family: var(--font-family-mono);
      font-size: 9pt;
      font-weight: 700;
      min-width: 32px;
      text-align: right;
    }

    /* Rate comparison */
    .kcd-rate-row {
      display: flex;
      justify-content: space-between;
      font-size: 9pt;
      margin-bottom: 6px;
    }

    .kcd-rate-item {
      display: flex;
      flex-direction: column;
      gap: 1px;
    }

    .kcd-rate-lbl {
      color: var(--txt-muted);
      font-size: 9pt;
    }

    .kcd-rate-val {
      font-family: var(--font-family-mono);
      font-weight: 700;
      font-size: 9pt;
    }

    /* Financial forecast */
    .kcd-fin {
      border-top: 1px solid rgba(0, 0, 0, 0.06);
      padding-top: 8px;
      margin-top: 6px;
    }

    .kcd-fin-amount {
      font-family: var(--font-family-mono);
      font-size: 15px;
      font-weight: 800;
      line-height: 1;
    }

    .kcd-fin-amount.penalty {
      color: var(--red);
    }

    .kcd-fin-amount.bonus {
      color: var(--green);
    }

    .kcd-fin-amount.ontrack {
      color: var(--blue);
      font-size: 13px;
      font-weight: 700;
    }

    .kcd-tile {
      cursor: pointer;
    }

    .kcd-tile:hover {

      box-shadow: 0 6px 20px rgba(0, 0, 0, 0.08);
    }

    .kcd-fin-desc {
      font-size: 9pt;
      color: var(--txt-muted);
      margin-top: 2px;
    }

    .kcd-fin-sub {
      font-size: 9pt;
      margin-top: 2px;
      font-weight: 600;
    }

    .kcd-fin-sub.avoidable {
      color: var(--green);
    }

    .kcd-fin-sub.locked {
      color: var(--green);
    }

    .kcd-fin-sub.growing {
      color: var(--red);
    }

    /* Overdue counter-up badge */
    .kcd-overdue-badge {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      font-size: 9pt;
      font-weight: 800;
      padding: 2px 8px;
      border-radius: 4px;
      background: var(--red);
      color: #fff;
      margin-bottom: 4px;
    }
