    .cdt-gantt-week.today-col {
      background: rgba(255, 0, 0, 0.06);
      color: var(--red);
    }

    .cdt-gantt-row {
      display: flex;
      align-items: center;
      border-bottom: 1px solid var(--border-2);
      min-height: 40px;
      position: relative;
    }

