    .cdt-gantt-name {
      width: 140px;
      min-width: 140px;
      padding: 0 12px;
    }

    .cdt-gantt-bars {
      flex: 1;
      position: relative;
      height: 40px;
      min-width: 800px;
    }

    .cdt-gantt-bar {
      position: absolute;
      height: 10px;
      border-radius: 4px;
      top: 10px;
      transition: opacity 0.15s;
      cursor: pointer;
    }

    .cdt-gantt-bar:hover {
      opacity: 0.8;
    }

    .cdt-gantt-bar.plan {
      background: rgba(41,55,141, 0.2);
      border: 1px solid rgba(41,55,141, 0.3);
