    /* Rich tooltip on bar hover */
    .cdt-tooltip {
      position: fixed;
      pointer-events: none;
      z-index: 10000;
      background: #1e1e1e;
      color: #e8ecf5;
      padding: 9px 13px;
      border-radius: 7px;
      font-family: var(--font-family-mono);
      font-size: 9pt;
      line-height: 1.5;
      white-space: pre;
      box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
      border: 1px solid rgba(255, 255, 255, 0.08);
      opacity: 0;
      transition: opacity 0.12s;
      max-width: 320px;
    }

    .cdt-tooltip.show {
      opacity: 1;
    }

    .cdt-tooltip strong {
      color: #fff;
      font-weight: 700;
    }

    .cdt-gantt-rigoOn {
