    /* â”€â”€ Wizard step navigator (Programme Gantt etc.) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
    .cdt-step-nav {
      display: flex;
      gap: 4px;
      padding: 4px;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 10px;
      margin-bottom: 10px;
      overflow-x: auto;
    }

    .cdt-step-nav .cdt-step {
      flex: 1 1 0;
      min-width: 150px;
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 8px 12px;
      border-radius: 7px;
      cursor: pointer;
      color: var(--txt-muted);
      font-size: 9pt;
      font-weight: 500;
      transition: background 0.15s, color 0.15s;
      white-space: nowrap;
      position: relative;
