    /* Step header banner with Prev / Step X of N Ã‚Â· Title / Next */
    .cdt-step-header {
      display: flex;
      align-items: center;
      gap: 14px;
      padding: 10px 14px;
      background: var(--surface-2);
      border: 1px solid var(--border);
      border-radius: 9px;
      margin-bottom: 10px;
