      border-color: var(--blue);
    }

    .cdt-step-btn-next:hover {
      background: var(--blue);
      color: #fff;
      filter: brightness(1.05);
    }

    /* Programme Gantt toolbar (filter + hint + today indicator + expand) */
    .cdt-gantt-toolbar {
      display: flex;
      gap: 10px;
      align-items: center;
      margin-bottom: 10px;
      flex-wrap: wrap;
    }

    .cdt-gantt-hint {
      font-size: 9pt;
