    /* â”€â”€ Gantt â€” extras for the new design â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
    .cdt-gantt-wrap.cdt-gantt-expanded {
      position: fixed;
      inset: 60px 16px 16px 16px;
      z-index: 8000;
      box-shadow: 0 20px 60px rgba(0, 0, 0, 0.25);
    }

    .cdt-gantt-rigon-col {
      width: 90px;
      min-width: 90px;
      padding: 0 10px;
      font-size: 9pt;
      font-weight: 700;
      letter-spacing: 0.5px;
      text-transform: uppercase;
      color: var(--txt-muted);
      text-align: left;
    }

    .cdt-gantt-wellid {
      font-family: var(--font-family-mono);
      font-size: 9pt;
      font-weight: 700;
      color: var(--blue);
      margin-bottom: 3px;
    }

    .cdt-gantt-status {
      font-size: 9pt;
      padding: 1px 7px;
    }

    /* Phase bar (overall mode) â€” slightly taller and centered for stripe overlay support */
    .cdt-gantt-bar.actual {
      height: 16px;
      top: 12px;
      border-radius: 3px;
    }

    /* Diagonal "slip" stripe overlay â€” sits on top of the actual bar */
    .cdt-gantt-stripe {
      position: absolute;
      top: 12px;
      height: 16px;
      border-radius: 3px;
      pointer-events: none;
      background-image: repeating-linear-gradient(
        45deg,
        var(--stripe-c, #f97316) 0,
        var(--stripe-c, #f97316) 4px,
        rgba(255, 255, 255, 0.85) 4px,
        rgba(255, 255, 255, 0.85) 8px
      );
      opacity: 0.95;
      z-index: 2;
    }

    /* Green completion checkmark badge */
    .cdt-gantt-check {
      position: absolute;
      top: 4px;
      transform: translateX(-50%);
      width: 14px;
      height: 14px;
      border-radius: 50%;
      background: #00B050;
      color: #fff;
      font-size: 9pt;
      font-weight: 700;
      line-height: 14px;
      text-align: center;
      box-shadow: 0 0 0 2px var(--surface);
      z-index: 4;
      pointer-events: none;
