    /* Diamond-shaped milestone marker */
    .cdt-gantt-diamond {
      position: absolute;
      top: 14px;
      width: 12px;
      height: 12px;
      transform: translateX(-50%) rotate(45deg);
      z-index: 4;
      cursor: pointer;
      box-shadow: 0 0 0 2px var(--surface);
    }

