    }

    .cdt-legend-diamond {
      position: relative;
      display: inline-block;
      transform: rotate(45deg);
      box-shadow: none;
      top: 0;
    }

    /* Milestone tracker */
    .cdt-ms-row {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 9px 12px;
      border-radius: 7px;
      background: #ffffff;
      border: 1px solid var(--border);
      border-left: 1px solid;
      margin-bottom: 6px;
      transition: box-shadow 0.15s;
    }

    .cdt-ms-row:hover {
      box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
    }

    .cdt-ms-row.overdue {
      border-left-color: #FF0000;
    }

    .cdt-ms-row.critical {
      border-left-color: #FFC000;
    }

    .cdt-ms-row.upcoming {
      border-left-color: #29378d;
    }

    .cdt-ms-row.done {
      border-left-color: #00B050;
    }

    html:not(.navbar-light) .cdt-ms-row {
      background: var(--surface);
      border-color: var(--border);
    }

    .cdt-ms-dot {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      font-size: 9pt;
      font-weight: 700;
    }

    .cdt-ms-dot.overdue {
      background: rgba(255, 0, 0, 0.15);
      color: var(--red);
    }

    .cdt-ms-dot.critical {
      background: rgba(255, 192, 0, 0.15);
      color: var(--amber);
    }

    .cdt-ms-dot.upcoming {
      background: var(--blue-soft);
      color: var(--blue);
    }

    .cdt-ms-dot.done {
      background: var(--green-soft);
      color: var(--green);
    }

    .cdt-ms-well {
      font-family: var(--font-family-mono);
      font-size: 9pt;
      font-weight: 700;
      color: var(--blue);
      min-width: 120px;
    }

    .cdt-ms-name {
      font-size: 12.5px;
      font-weight: 600;
      color: var(--txt-1);
      flex: 1;
    }

    .cdt-ms-owner {
      font-size: 9pt;
      color: var(--txt-muted);
      min-width: 110px;
    }

    .cdt-ms-dates {
      text-align: right;
      min-width: 120px;
    }

    .cdt-ms-planned {
      font-family: var(--font-family-mono);
      font-size: 9pt;
      color: var(--txt-muted);
    }

    .cdt-ms-var {
      font-family: var(--font-family-mono);
      font-size: 9pt;
      font-weight: 700;
    }

    .cdt-ms-var.late {
      color: var(--red);
    }

    .cdt-ms-var.early {
      color: var(--green);
    }

    .cdt-ms-var.ontime {
      color: var(--teal);
    }

    /* Critical path */
    .cdt-cp-node {
      display: flex;
      align-items: center;
      gap: 0;
      overflow-x: auto;
      padding: 12px 0;
    }

    .cdt-cp-step {
      display: flex;
      flex-direction: column;
      align-items: center;
      min-width: 110px;
      position: relative;
    }

    .cdt-cp-circle {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      border: 1px solid;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 9pt;
      font-weight: 700;
      z-index: 1;
      flex-shrink: 0;
    }

    .cdt-cp-circle.critical {
      background: rgba(255, 0, 0, 0.15);
      border-color: var(--red);
      color: var(--red);
    }

    .cdt-cp-circle.float {
      background: rgba(41,55,141, 0.1);
      border-color: var(--blue);
      color: var(--blue);
    }

    .cdt-cp-circle.done {
      background: var(--green-soft);
      border-color: var(--green);
      color: var(--green);
    }

    .cdt-cp-line {
      flex: 1;
      height: 1px;
      min-width: 30px;
      align-self: center;
    }

    .cdt-cp-line.critical {
      background: var(--red);
    }

    .cdt-cp-line.float {
      background: var(--blue);
    }

    .cdt-cp-lbl {
      font-size: 9pt;
      font-weight: 600;
      color: var(--txt-2);
      margin-top: 5px;
      text-align: center;
      max-width: 100px;
      line-height: 1.3;
    }

    .cdt-cp-dur {
      font-size: 9pt;
      color: var(--txt-muted);
      margin-top: 2px;
      font-family: var(--font-family-mono);
    }

    .cdt-cp-float {
      font-size: 9pt;
      font-weight: 700;
      color: var(--green);
    }

    /* What-if slider */
    .cdt-whatif-wrap {
      background: var(--surface-2);
      border: 1px solid var(--border);
      border-radius: 9px;
      padding: 14px 18px;
      margin-top: 12px;
    }

    .cdt-whatif-label {
      font-size: 9pt;
      font-weight: 600;
      color: var(--txt-1);
      margin-bottom: 8px;
      display: flex;
      justify-content: space-between;
    }

    .cdt-impact-box {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 10px;
      margin-top: 12px;
    }

    .cdt-impact-item {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 7px;
      padding: 8px 12px;
      text-align: center;
    }

    .cdt-impact-label {
      font-size: 9pt;
      color: var(--txt-muted);
      text-transform: uppercase;
      letter-spacing: 0.5px;
      margin-bottom: 3px;
    }

    .cdt-impact-val {
      font-family: var(--font-family-mono);
      font-size: 15px;
      font-weight: 800;
    }

    /* Heat Calendar */
    .cdt-cal-grid {
      display: grid;
      grid-template-columns: 60px repeat(16, 1fr);
      gap: 4px;
    }

    .cdt-cal-header {
      font-size: 9pt;
      font-weight: 700;
      text-align: center;
      color: var(--txt-muted);
      padding: 4px 0;
    }

    .cdt-cal-label {
      font-size: 9pt;
      font-weight: 600;
      color: var(--txt-2);
      padding: 4px 6px;
      display: flex;
      align-items: center;
    }

    .cdt-cal-cell {
      border-radius: 5px;
      padding: 4px 3px;
      text-align: center;
      cursor: pointer;
      transition: all 0.15s;
      min-height: 32px;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
    }

    .cdt-cal-cell:hover {
      filter: brightness(0.9);
    }

    .cdt-cal-cell.quiet {
      background: rgba(22, 163, 74, 0.1);
      border: 1px solid rgba(22, 163, 74, 0.2);
    }

    .cdt-cal-cell.moderate {
      background: rgba(255, 192, 0, 0.12);
      border: 1px solid rgba(255, 192, 0, 0.25);
    }

    .cdt-cal-cell.busy {
      background: rgba(255, 0, 0, 0.1);
      border: 1px solid rgba(255, 0, 0, 0.25);
    }

    .cdt-cal-cell.rigon {
      background: rgba(255, 0, 0, 0.18);
      border: 1px solid var(--red);
    }

    .cdt-cal-cell.empty {
      background: rgba(0, 0, 0, 0.025);
      border: 1px solid var(--border-2);
    }

    .cdt-cal-cell.today {
      box-shadow: 0 0 0 2px var(--blue);
    }

    .cdt-cal-count {
      font-family: var(--font-family-mono);
      font-size: 9pt;
      font-weight: 700;
      line-height: 1;
    }

    .cdt-cal-sub {
      font-size: 8px;
      color: var(--txt-muted);
      margin-top: 1px;
    }

    /* Delay cascade */
    .cdt-delay-card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 9px;
      padding: 16px 18px;
      margin-bottom: 12px;
    }

    .cdt-delay-head {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-bottom: 10px;
    }

    .cdt-cascade-row {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 6px 0;
      border-bottom: 1px solid var(--border-2);
      font-size: 9pt;
    }

    .cdt-cascade-row:last-child {
      border-bottom: none;
    }

    .cdt-cascade-arrow {
      color: var(--txt-muted);
      font-size: 14px;
      flex-shrink: 0;
    }

    .cdt-cascade-phase {
      flex: 1;
      color: var(--txt-2);
    }

    .cdt-cascade-slip {
      font-family: var(--font-family-mono);
      font-weight: 700;
      min-width: 50px;
      text-align: right;
    }

    .cdt-recovery-row {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 7px 12px;
      background: var(--surface-2);
      border: 1px solid var(--border);
      border-radius: 7px;
      margin-bottom: 6px;
    }

    .cdt-recovery-rank {
      font-size: 18px;
      font-weight: 800;
      font-family: var(--font-family-mono);
      min-width: 28px;
      color: var(--blue);
    }

    .cdt-recovery-desc {
      flex: 1;
      font-size: 9pt;
      color: var(--txt-1);
    }

    .cdt-recovery-net {
      font-family: var(--font-family-mono);
      font-size: 9pt;
      font-weight: 700;
      color: var(--green);
      min-width: 80px;
      text-align: right;
    }

    /* â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
       GLOBAL DARK THEME â€” applied whenever html does NOT
       have `.navbar-light`. Drives every page by flipping
       the shared CSS tokens; page-specific blocks below
       /* add small polish on top. No JS or markup changes.
       â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• */
    html:not(.navbar-light) {
      --bg: #0b1538;
      --surface: #112448;
      --surface-2: #172d54;
      --border: rgba(255, 255, 255, 0.08);
      --border-2: rgba(255, 255, 255, 0.05);
