    }
    .sb-sub-item:hover { background: rgba(255,255,255,0.04); }
    .sb-sub-item.active { background: rgba(201,160,74,0.08); }
    .sb-dot { width: 7px; height: 7px; border-radius: 50%; border: 1.5px solid rgba(160,185,220,0.3); flex-shrink: 0; }
    .sb-dot.on   { background: #c9a04a; border-color: #c9a04a; box-shadow: 0 0 4px rgba(201,160,74,0.5); }
    .sb-dot.blue { background: #4e8ef7; border-color: #4e8ef7; }
