    .sb-sub-icon { width: 16px; height: 16px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
    .sb-sub-icon svg { width: 14px; height: 14px; stroke: rgba(140,165,210,0.5); fill: none; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; transition: stroke 0.15s; }
