    .sb-sub-badge { font-size: 9pt; font-weight: 600; padding: 2px 7px; border-radius: 20px; flex-shrink: 0; }

    /* â”€â”€ Sidebar light theme (blue accents on navy) â”€â”€ */
    html.navbar-light .sidebar {
      background: #0F2460;
      border-right: 1px solid rgba(255,255,255,0.06);
    }
    html.navbar-light .sb-brand { border-bottom-color: rgba(255,255,255,0.06); }
    html.navbar-light .sb-logo-mark { background: #ffffff; }
    html.navbar-light .sb-brand-name { color: rgba(255,255,255,0.92); }
    html.navbar-light .sb-brand-sub { color: rgba(255,255,255,0.35); }
    html.navbar-light .sb-section-label { color: rgba(255,255,255,0.35); }
    html.navbar-light .sb-item { color: rgba(255,255,255,0.85); }
