    .afilt-opt-check svg { width: 11px; height: 11px; }

    .afilt-foot {
      display: flex; align-items: center; justify-content: flex-end; gap: 10px;
      padding: 14px 18px; border-top: 1px solid var(--border);
      background: var(--surface); flex-shrink: 0;
    }
    .afilt-btn {
      appearance: none;
      padding: 9px 22px; font: inherit; font-size: 9.5pt; font-weight: 600;
      border-radius: 8px; cursor: pointer;
      transition: background .12s, border-color .12s, color .12s, box-shadow .12s;
    }
    .afilt-btn--ghost { background: var(--surface); border: 1px solid var(--border); color: var(--txt-1); }
    .afilt-btn--ghost:hover { background: var(--surface-2); }
    .afilt-btn--primary { background: #29378d; border: 1px solid #29378d; color: #fff; }
    .afilt-btn--primary:hover { box-shadow: 0 4px 12px rgba(41,55,141, 0.3); }

    /* Too narrow to push content — below 1199px the Advanced Filter always
       falls back to a floating overlay (launcher-button toggle), regardless
       of the user's pin preference. Pinning only pushes layout on desktop.
       NOTE: the desktop rule ".afilt-dock.is-pinned .afilt-panel" sets
       width/height:100% + transform:none so the panel fills the pushed
       dock — with the dock forced to 0 width below, that combination
       collapses the panel to ~1px. Every one of those properties must be
       re-declared here (not just position/box-shadow) or it stays broken. */
    @media (max-width: 1199px) {
      .afilt-dock.is-open.is-pinned { flex-basis: 0; width: 0; }
      .afilt-dock.is-pinned .afilt-panel {
        position: absolute;
        top: 0; left: 0; bottom: 0;
        width: 86vw; max-width: 340px; height: auto;
        transform: translateX(-100%);
        box-shadow: 12px 0 32px rgba(15, 23, 42, 0.18);
      }
      .afilt-dock.is-open.is-pinned .afilt-panel {
        transform: translateX(0);
      }
      .afilt-dock .afilt-panel { width: 86vw; max-width: 340px; }
      /* Pinning has no effect below this width, so hide the control to avoid confusion */
      .afilt-pin { display: none; }
    }
    @media (max-width: 480px) {
      .afilt-dock .afilt-panel,
      .afilt-dock.is-pinned .afilt-panel { width: 92vw; max-width: 320px; }
    }

    /* ──────────────────────────────────────────────────────────
       MOBILE SIDEBAR DRAWER — below 1199px the sidebar is hidden
       off-canvas by default and toggled via the .nb-menu-btn
       hamburger; opens as a full overlay drawer with a backdrop.
       ────────────────────────────────────────────────────────── */
    .sb-mobile-close { display: none; }
    .sb-mobile-backdrop {
      position: fixed; inset: 0;
      background: rgba(15, 23, 42, 0.5);
      opacity: 0; pointer-events: none;
      transition: opacity .25s ease;
      z-index: 1490;
    }
    @media (max-width: 1199px) {
      .sidebar {
        position: fixed; top: 0; left: 0; height: 100vh;
        z-index: 1500;
        transform: translateX(-100%);
        transition: transform .25s cubic-bezier(0.32, 0.72, 0, 1);
        box-shadow: none;
      }
      .sidebar.is-mobile-open {
        transform: translateX(0);
        box-shadow: 12px 0 32px rgba(15, 23, 42, 0.28);
      }
      /* The mobile drawer never carries .is-collapsed (see sidebar.component.html —
         the icon-rail class is suppressed while the drawer is open), so it always
         renders the full menu with labels regardless of the desktop rail preference. */
      .sb-collapse-btn { display: none; }
      .sb-mobile-close { display: inline-flex; }
      .sb-mobile-backdrop.is-open { opacity: 1; pointer-events: auto; }
    }

