    .pr-stat::before { content: ''; position: absolute; top: 0; left: 0; bottom: 0; 
      width: 3px; border-radius: 9px 0 0 9px; }
    .pr-stat.c-red::before    { background: var(--red); }
    .pr-stat.c-green::before  { background: var(--green); }
