    .pr-stat.c-amber::before  { background: var(--amber); }
    .pr-stat-label { font-size: 9pt; color: var(--txt-muted); font-weight: 600; letter-spacing: 0.6px; text-transform: uppercase; margin-bottom: 6px; }
