    .pa-tbl { width:100%; border-collapse:collapse; }
    .pa-tbl th { padding:9px 12px; font-size: 9pt; font-weight:700; letter-spacing:0.6px; text-transform:uppercase; color:var(--txt-muted); background:var(--surface-2); border-bottom:1px solid var(--border); text-align:left; white-space:nowrap; }
    .pa-tbl td { padding:10px 12px; font-size:9pt; border-bottom:1px solid var(--border-2); vertical-align:middle; }
    .pa-tbl tr:last-child td { border-bottom:none; }
    .pa-tbl tr:hover td { background:rgba(0,0,0,0.015); }
    .pa-tbl tr.crit td { background:rgba(255,0,0,0.03); }

    /* Recommended Actions */
    .pa-rec-card { border:1px solid var(--border); }
    .pa-rec-tbl th { background:transparent; }
    .pa-rec-wellid { font-family:var(--font-family-mono); font-size:9pt; font-weight:600; color:#29378d; text-decoration:none; }
    .pa-rec-wellid:hover { text-decoration:underline; }
    .pa-rec-info { display:inline-flex; align-items:center; gap:5px; font-size:9pt; color:#29378d; text-decoration:none; cursor:pointer; }
    .pa-rec-info:hover { text-decoration:underline; }
    .pa-rec-link { font-size:9pt; font-weight:600; color:#29378d; text-decoration:none; }
    .pa-rec-link:hover { text-decoration:underline; }

    /* Rate bar (inline mini bar in table) */
    .pa-rate-bar { display:flex; align-items:center; gap:7px; }
    .pa-rate-track { flex:1; max-width:100px; height:7px; background:rgba(0,0,0,0.06); border-radius:4px; overflow:visible; position:relative; }
    .pa-rate-fill  { height:100%; border-radius:4px; }
    .pa-rate-ask-marker { position:absolute; top:-3px; height:13px; width:2px; background:var(--txt-1); border-radius:1px; }
    .pa-rate-val { font-family:var(--font-family-mono); font-size: 9pt; font-weight:600; min-width:40px; }

    /* Trend spark */
    .pa-spark { display:inline-block; }
    .pa-spark svg { display:block; }

    /* Buffer indicator */
    .pa-buf { font-family:var(--font-family-mono); font-size:9pt; font-weight:700; white-space:nowrap; }
    .pa-buf.pos { color:var(--green); } .pa-buf.neg { color:var(--red); }

    /* Crew-add recommendation */
    .pa-crew-rec { display:flex; align-items:center; gap:5px; }
    .pa-crew-rec-add { background:var(--red-soft); color:var(--red); border:1px solid var(--red-bd); font-size: 9pt; font-weight:700; padding:2px 8px; border-radius:4px; white-space:nowrap; }
    .pa-crew-rec-ok  { background:var(--green-soft); color:var(--green); border:1px solid var(--green-bd); font-size: 9pt; font-weight:600; padding:2px 8px; border-radius:4px; }

    /* Cost vs penalty pill */
    .pa-cpill { font-size: 9pt; font-weight:600; padding:2px 7px; border-radius:4px; white-space:nowrap; }
    .pa-cpill.save { background:var(--green-soft); color:var(--green); border:1px solid var(--green-bd); }
    .pa-cpill.loss  { background:var(--red-soft); color:var(--red); border:1px solid var(--red-bd); }
    .pa-cpill.none  { background:var(--surface-2); color:var(--txt-muted); border:1px solid var(--border); }

    /* What-if panel */
    .pa-whatif-grid { display:grid; grid-template-columns:repeat(2,1fr); gap:10px; }
    @media(max-width:900px){ .pa-whatif-grid{ grid-template-columns:1fr; } }
    .pa-wi-card { background:var(--surface-2); border:1px solid var(--border); border-radius:10px; padding:14px; }
    .pa-wi-head { font-size:9pt; font-weight:600; color:var(--txt-1); margin-bottom:10px; display:flex; justify-content:space-between; align-items:center; }
    .pa-wi-header { margin-bottom:10px; }
    .pa-wi-title-card {
      display:flex; align-items:center; gap:10px;
