    .pa-wi-wf-impact {
      display:grid; grid-template-columns:repeat(4,1fr); gap:8px;
      margin-bottom:14px;
    }
    .pa-wi-wf-impact-cell {
      background:#fff; border:1px solid #e2e8f0; border-radius:8px;
      padding:9px 10px;
    }
    .pa-wi-wf-impact-label { font-size: 9pt; font-weight:700; letter-spacing:0.4px; text-transform:uppercase; color:#7F7F7F; }
    .pa-wi-wf-impact-val   { font-size:9pt; font-weight:700; color:#0f172a; margin-top:3px; font-family:var(--font-family-mono); }
    .pa-wi-wf-steps { display:flex; flex-direction:column; gap:10px; }
