    /* Backward schedule / Gantt */
    .pa-gantt-wrap { overflow-x:auto; }
    .pa-gantt-tbl { width:100%; border-collapse:collapse; min-width:600px; }
    .pa-gantt-tbl th { padding:8px 12px; font-size: 9pt; font-weight:700; letter-spacing:0.6px; text-transform:uppercase; color:var(--txt-muted); background:var(--surface-2); border-bottom:1px solid var(--border); text-align:left; }
    .pa-gantt-tbl td { padding:9px 12px; font-size:9pt; border-bottom:1px solid var(--border-2); vertical-align:middle; }
    .pa-gantt-tbl tr:last-child td { border-bottom:none; }
    .pa-gantt-bar-wrap { position:relative; height:20px; background:rgba(0,0,0,0.04); border-radius:4px; overflow:hidden; }
    .pa-gantt-bar { height:100%; border-radius:4px; position:absolute; display:flex; align-items:center; padding:0 6px; font-size: 9pt; font-weight:700; color:#fff; white-space:nowrap; overflow:hidden; }
    .pa-gantt-today { position:absolute; top:0; bottom:0; width:2px; background:var(--red); opacity:0.8; }
    .pa-latest-start { font-family:var(--font-family-mono); font-size: 9pt; font-weight:700; }
    .pa-bs-row { cursor:help; transition:background .12s ease; }
    .pa-bs-row:hover { background:rgba(41,55,141,0.05); }
    .pa-late-warn { color:var(--red); }
    .pa-on-time  { color:var(--green); }

    /* Programme-level forecast */
