      display:grid; grid-template-columns:115px 1fr 68px 62px;
      align-items:center; gap:8px;
      padding:5px 6px; border-radius:6px;
      cursor:pointer;
      transition:background .12s ease, box-shadow .12s ease;
    }
    .pa-prog-fc-row:hover { background:rgba(41,55,141,0.06); box-shadow:inset 3px 0 0 #29378d; }
    .pa-prog-legend {
