    .lp-sync-bar svg { width:14px; height:14px; color:#ca8a04; flex-shrink:0; }
    .lp-sync-btn {
      margin-left:auto; padding:4px 12px; background:#ca8a04; color:#fff;
      border:none; border-radius:5px; font-size: 9pt; font-weight:600;
      cursor:pointer; font-family:inherit; transition:background 0.15s;
    }
    .lp-sync-btn:hover { background:#a16207; }
    .lp-sync-dot { width:8px; height:8px; border-radius:50%; flex-shrink:0; }
    .lp-sync-dot.pending { background:#FFC000; box-shadow:0 0 6px rgba(255,192,0,0.5); animation:aiPulse 2s infinite; }
    .lp-sync-dot.synced  { background:#00B050; }

    /* KPI strip */
    .lp-strip { display:grid; grid-template-columns:repeat(6,1fr); gap:10px; 
      margin-bottom:10px; }
    @media(max-width:1200px){ .lp-strip{ grid-template-columns:repeat(3,1fr); } }
    /* ── KPI strip — matches cmdoverview card design ── */
    .lp-kpi { background:var(--surface); border:1px solid var(--border); border-radius:9px; padding:10px; position:relative; overflow:hidden; display:flex; flex-direction:column; cursor:default; transition:transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease; }
    .lp-kpi:hover { box-shadow:0 4px 16px rgba(0,0,0,0.08); }
    .lp-kpi::before { content:''; position:absolute; top:0; left:0; right:0; bottom:auto; width:auto; height:1px; border-radius:9px 9px 0 0; opacity:0.95; }
    .lp-kpi.c-green::before  { background:var(--green); }
    .lp-kpi.c-blue::before   { background:var(--blue); }
    .lp-kpi.c-amber::before  { background:var(--amber); }
    .lp-kpi.c-red::before    { background:var(--red); }
    .lp-kpi.c-teal::before   { background:var(--teal); }
    .lp-kpi.c-purple::before { background:#29378d; }
    .lp-kpi-head { display:flex; align-items:center; justify-content:space-between; gap:8px; margin-bottom:10px; }
    .lp-kpi-label { font-size:8pt; font-weight:600; letter-spacing:0.7px; text-transform:uppercase; color:var(--txt-muted); margin:0; line-height:1.2; flex:1; }
    .lp-kpi-icon { width:26px; height:26px; flex-shrink:0; border-radius:7px; display:inline-flex; align-items:center; justify-content:center; }
    .lp-kpi-icon svg { width:14px; height:14px; }
    .lp-kpi.c-green  .lp-kpi-icon { background:rgba(0,176,80,0.12);   color:var(--green); }
    .lp-kpi.c-blue   .lp-kpi-icon { background:rgba(41,55,141,0.12); color:var(--blue); }
    .lp-kpi.c-amber  .lp-kpi-icon { background:rgba(255,192,0,0.14);  color:var(--amber); }
    .lp-kpi.c-red    .lp-kpi-icon { background:rgba(255,0,0,0.12);    color:var(--red); }
    .lp-kpi.c-teal   .lp-kpi-icon { background:rgba(0,176,240,0.12);  color:var(--teal); }
