    .lp-kpi-sub { font-size:9pt; color:var(--txt-dim); margin-top:0; line-height:1.4; }

    /* Anomaly badge */
    .lp-anomaly { display:inline-flex; align-items:center; gap:4px; font-size: 9pt; font-weight:700; padding:2px 7px; border-radius:4px; letter-spacing:0.4px; }
