    .lp-anomaly.warn     { background:rgba(255,192,0,0.1);  color:#FFC000; border:1px solid rgba(255,192,0,0.25); }
    .lp-anomaly.info     { background:var(--blue-soft);    color:var(--blue); border:1px solid var(--blue-bd); }
    .lp-anomaly.none     { background:var(--green-soft);   color:var(--green); border:1px solid var(--green-bd); }

    /* P-rating achievement bar */
    .lp-ach-wrap { display:flex; align-items:center; gap:8px; }
    .lp-ach-track { flex:1; max-width:120px; height:8px; background:rgba(0,0,0,0.06); border-radius:4px; overflow:hidden; position:relative; }
    .lp-ach-fill  { height:100%; border-radius:4px; transition:width 0.4s; }
