    .lp-att-daterange label, .lp-att-wellfilter label {
      font-size: 9pt; font-weight:700; letter-spacing:0.4px;
      text-transform:uppercase; color:var(--txt-muted);
    }
    .lp-att-daterange input[type="date"],
