    /* Hide dq-toolbar on SH page â€” darktheme uses hero controls instead */
    #page-selfheal > .dq-toolbar { display:none; }

    /* Hero / Header card â€” matches darktheme .sh-header-card */
    .sh-hero { background:var(--surface); border:1px solid rgba(201,160,74,0.15);
      border-radius:10px; padding:14px; color:var(--txt-1);
      display:flex; align-items:center; gap:14px; margin-bottom:10px;
      position:relative; overflow:hidden; flex-wrap:wrap; }
    .sh-hero::before { display:none; }
    .sh-hero-icon { width:40px; height:40px; border-radius:10px; background:rgba(78,142,247,0.1); border:1px solid rgba(78,142,247,0.2); display:flex; align-items:center; justify-content:center; flex-shrink:0; }
    .sh-hero-icon svg { width:20px; height:20px; stroke:#4e8ef7; }
    .sh-hero-body { flex:1; position:relative; }
    .sh-hero-title { font-size:16px; font-weight:600; margin-bottom:3px; display:flex; align-items:center; gap:8px; color:var(--txt-1); }
    .sh-at-badge { background:#1F3864; color:#fff; font-size: 9pt; font-weight:700; padding:2px 8px; border-radius:4px; letter-spacing:0.5px; border:none; }
    .sh-hero-sub { font-size:9pt; color:var(--txt-muted); margin-top:6px; line-height:1.5; }
    .sh-hero-actions { display:flex; align-items:center; gap:8px; position:relative; flex-shrink:0; flex-wrap:wrap; }
    .sh-ctrl-btn { padding:6px 14px; background:var(--surface); border:1px solid rgba(201,160,74,0.15); border-radius:6px; font-family:inherit; font-size: 9pt; color:var(--txt-1); cursor:pointer; display:flex; align-items:center; gap:5px; transition:all 0.15s; }
    .sh-ctrl-btn:hover { border-color:rgba(201,160,74,0.35); }
    .sh-run-btn { padding:7px 18px; background:#1F3864; border:none; border-radius:6px; font-family:inherit; font-size: 9pt; font-weight:700; color:#fff; cursor:pointer; display:flex; align-items:center; gap:6px; letter-spacing:0.5px; transition:all 0.15s; }
    .sh-run-btn:hover { opacity:0.9; transform:translateY(-1px); }
    .sh-run-btn svg { width:13px; height:13px; stroke:#f5c842; }

    /* KPI strip — 6 cards (cmdoverview design system) */
    .sh-kpi-strip { display:grid; grid-template-columns:repeat(6,1fr); gap:10px; margin-bottom:10px; }
    @media(max-width:1200px){ .sh-kpi-strip{ grid-template-columns:repeat(3,1fr); } }
    .sh-kpi { position:relative; background:var(--surface); border:1px solid var(--border); border-radius:9px; padding:10px; display:flex; flex-direction:column; min-width:0; overflow:hidden; transition:transform 0.15s ease,box-shadow 0.15s ease,border-color 0.15s ease; }
    .sh-kpi::before { content:''; position:absolute; top:0; left:0; right:0; bottom:auto; width:auto; height:1px; border-radius:9px 9px 0 0; opacity:0.95; }
    .sh-kpi:hover { box-shadow:0 4px 16px rgba(0,0,0,0.08); }
    .sh-kpi.cyan::before   { background:#00B0F0; }
    .sh-kpi.green::before  { background:#00B050; }
    .sh-kpi.amber::before  { background:#FFC000; }
    .sh-kpi.red::before    { background:#FF0000; }
    .sh-kpi.purple::before { background:#29378d; }
    .sh-kpi-head { display:flex; align-items:flex-start; justify-content:space-between; gap:6px; margin-bottom:10px; }
    .sh-kpi-label { font-size:8pt; font-weight:600; color:var(--txt-muted); text-transform:uppercase; letter-spacing:0.7px; line-height:1.3; flex:1; }
    .sh-kpi-icon { flex:none; width:26px; height:26px; border-radius:7px; display:flex; align-items:center; justify-content:center; }
    .sh-kpi-icon svg { width:14px; height:14px; }
    .sh-kpi-icon--cyan   { background:rgba(0,176,240,0.12);  color:#00B0F0; }
    .sh-kpi-icon--green  { background:rgba(0,176,80,0.12);   color:#00B050; }
    .sh-kpi-icon--amber  { background:rgba(255,192,0,0.12);  color:#FFC000; }
    .sh-kpi-icon--red    { background:rgba(255,0,0,0.12);    color:#FF0000; }
    .sh-kpi-icon--blue   { background:rgba(41,55,141,0.12); color:#29378d; }
    .sh-kpi-val { font-family:var(--font-family-mono); font-size:20pt; font-weight:700; line-height:1; margin:0 0 6px; }
    .sh-kpi-unit { font-size:10pt; }
    .sh-kpi-val.green  { color:#00B050; } .sh-kpi-val.amber  { color:#FFC000; }
    .sh-kpi-val.red    { color:#FF0000; } .sh-kpi-val.purple { color:#29378d; }
    .sh-kpi-sub { font-size:9pt; color:var(--txt-dim); margin-top:0; line-height:1.4; }

