    .sh-escalate-btn{ padding:4px 14px; background:rgba(78,142,247,0.08); color:var(--accent); border:1px solid rgba(78,142,247,0.25); border-radius:6px; font-family:inherit; font-size: 9pt; font-weight:600; cursor:pointer; transition:all 0.15s; }
