    /* Confidence bar (thin) */
    .sh-conf-bar-wrap { display:flex; align-items:center; gap:6px; }
    .sh-conf-track { width:40px; height:5px; background:rgba(255,255,255,0.08); border-radius:3px; overflow:hidden; }
