    .sh-err-badge { font-size: 9pt; font-weight:600; padding:2px 8px; border-radius:4px; background:rgba(232,196,122,0.12); color:#e8c47a; border:1px solid rgba(232,196,122,0.25); }
    .sh-action-cell { white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width:200px; font-size: 9pt; color:var(--txt-2); }
    .sh-method-tag { font-size: 9pt; font-weight:600; padding:2px 8px; border-radius:4px; background:rgba(78,142,247,0.1); color:var(--accent); border:1px solid rgba(78,142,247,0.2); }
    .sh-status-open { font-size: 9pt; font-weight:600; padding:2px 8px; border-radius:4px; background:rgba(232,196,122,0.12); color:#e8c47a; border:1px solid rgba(232,196,122,0.25); }
    .sh-approve-icon { width:22px; height:22px; border-radius:4px; border:1px solid rgba(74,222,128,0.3); color:#00B050; background:rgba(74,222,128,0.1); display:inline-flex; align-items:center; justify-content:center; cursor:pointer; font-size:9pt; font-weight:700; }
