    /* Pagination */
    .sh-pagination { display:flex; align-items:center; gap:4px; padding:10px 0; font-size:9pt; color:var(--txt-muted); }
    .sh-page-btn { width:26px; height:26px; border-radius:4px; border:1px solid rgba(201,160,74,0.12); background:var(--surface); display:flex; align-items:center; justify-content:center; cursor:pointer; font-size: 9pt; color:var(--txt-muted); transition:all 0.15s; }
    .sh-page-btn:hover { background:var(--surface-2); }
    .sh-page-btn.active { background:rgba(78,142,247,0.15); color:var(--accent); border-color:rgba(78,142,247,0.3); }

    /* Run healing animation */
    @keyframes healPulse { 0%,100%{box-shadow:0 0 0 0 rgba(58,123,222,0.4)} 50%{box-shadow:0 0 0 8px rgba(58,123,222,0)} }
    .sh-run-btn.scanning { animation:healPulse 1.2s infinite; }

