    .pi-inf-badge.info     { background:var(--blue-soft); color:var(--blue); border:1px solid var(--blue-bd); }
    .pi-inf-badge.clean    { background:var(--green-soft); color:var(--green); border:1px solid var(--green-bd); }

    /* Inflation bar (rate vs norm visual) */
