       KPI COUNTDOWN TIMERS
       â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• */

    .kcd-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:10px; }
    @media(max-width:1200px){ .kcd-grid{ grid-template-columns:repeat(2,1fr); } }

    /* Individual tile */
    .kcd-tile { border-radius:10px; border:1px solid; padding:14px 16px; position:relative; overflow:hidden; transition:box-shadow 0.2s; }
    .kcd-tile:hover { box-shadow:0 4px 16px rgba(0,0,0,0.1); }
    .kcd-tile.critical { background:rgba(255,0,0,0.04);  border-color:rgba(255,0,0,0.3); }
    .kcd-tile.atrisk   { background:rgba(255,192,0,0.04);  border-color:rgba(255,192,0,0.3); }
    .kcd-tile.ontrack  { background:rgba(41,55,141,0.03);  border-color:rgba(41,55,141,0.18); }
    .kcd-tile.bonus    { background:rgba(0,176,80,0.04);  border-color:rgba(0,176,80,0.3); }
    .kcd-tile.overdue  { background:rgba(255,0,0,0.07);  border-color:rgba(255,0,0,0.5); animation:kcdPulse 2s infinite; }

    @keyframes kcdPulse {
      0%,100% { border-color:rgba(255,0,0,0.5); }
      50%      { border-color:rgba(255,0,0,0.9); box-shadow:0 0 0 3px rgba(255,0,0,0.12); }
    }

    /* Tile header */
    .kcd-tile-head  { display:flex; align-items:center; justify-content:space-between; margin-bottom:8px; }
    .kcd-tile-well  { font-family:var(--font-family-mono); font-size:9pt; font-weight:700; color:var(--txt-1); }
    .kcd-tile-badge { font-size: 9pt; font-weight:800; padding:2px 8px; border-radius:10px; text-transform:uppercase; letter-spacing:0.4px; }
    .kcd-tile-badge.critical { background:rgba(255,0,0,0.12); color:var(--red); border:1px solid rgba(255,0,0,0.3); }
    .kcd-tile-badge.atrisk   { background:rgba(255,192,0,0.12);  color:var(--amber); border:1px solid rgba(255,192,0,0.3); }
    .kcd-tile-badge.ontrack  { background:var(--blue-soft);       color:var(--blue);  border:1px solid var(--blue-bd); }
    .kcd-tile-badge.bonus    { background:var(--green-soft);      color:var(--green); border:1px solid var(--green-bd); }
    .kcd-tile-badge.overdue  { background:rgba(255,0,0,0.2);    color:var(--red);   border:1px solid rgba(255,0,0,0.5); }

    /* Countdown label */
    .kcd-timer-label { font-size: 9pt; font-weight:700; letter-spacing:0.7px; text-transform:uppercase; color:var(--txt-muted); margin-bottom:3px; }

    /* The big timer digits */
    .kcd-timer { font-family:var(--font-family-mono); font-size:22px; font-weight:800; letter-spacing:1px; line-height:1; margin-bottom:2px; }
    .kcd-timer.critical { color:var(--red); }
    .kcd-timer.atrisk   { color:var(--amber); }
    .kcd-timer.ontrack  { color:var(--blue); }
    .kcd-timer.bonus    { color:var(--green); }
    .kcd-timer.overdue  { color:var(--red); }

    .kcd-timer-units { display:flex; gap:6px; margin-bottom:8px; }
    .kcd-timer-unit  { text-align:center; }
    .kcd-timer-unit .digits { font-family:var(--font-family-mono); font-size:20px; font-weight:800; line-height:1; }
    .kcd-timer-unit .unit-lbl { font-size:8.5px; text-transform:uppercase; letter-spacing:0.5px; color:var(--txt-muted); font-weight:600; }
    .kcd-timer-sep { font-size:20px; font-weight:800; color:var(--txt-muted); line-height:1; align-self:flex-start; padding-top:1px; }

    /* Progress bar */
    .kcd-prog-row { display:flex; align-items:center; gap:6px; margin-bottom:6px; }
    .kcd-prog-track { flex:1; height:6px; background:rgba(0,0,0,0.07); border-radius:3px; overflow:hidden; }
    .kcd-prog-fill  { height:100%; border-radius:3px; transition:width 0.5s; }
    .kcd-prog-pct   { font-family:var(--font-family-mono); font-size: 9pt; font-weight:700; min-width:32px; text-align:right; }

    /* Rate comparison */
    .kcd-rate-row { display:flex; justify-content:space-between; font-size: 9pt; margin-bottom:6px; }
    .kcd-rate-item { display:flex; flex-direction:column; gap:1px; }
    .kcd-rate-lbl  { color:var(--txt-muted); font-size: 9pt; }
    .kcd-rate-val  { font-family:var(--font-family-mono); font-weight:700; font-size: 9pt; }

    /* Financial forecast */
    .kcd-fin { border-top:1px solid rgba(0,0,0,0.06); padding-top:8px; margin-top:6px; }
    .kcd-fin-amount { font-family:var(--font-family-mono); font-size:15px; font-weight:800; line-height:1; }
    .kcd-fin-amount.penalty { color:var(--red); }
    .kcd-fin-amount.bonus   { color:var(--green); }
    .kcd-fin-amount.ontrack { color:var(--blue); font-size:13px; font-weight:700; }

    .kcd-tile { cursor:pointer; }
    .kcd-tile:hover { box-shadow:0 6px 20px rgba(0,0,0,0.08); }
    .kcd-fin-desc { font-size: 9pt; color:var(--txt-muted); margin-top:2px; }
    .kcd-fin-sub  { font-size: 9pt; margin-top:2px; font-weight:600; }
    .kcd-fin-sub.avoidable { color:var(--green); }
    .kcd-fin-sub.locked    { color:var(--green); }
    .kcd-fin-sub.growing   { color:var(--red); }

    /* Overdue counter-up badge */
    .kcd-overdue-badge { display:inline-flex; align-items:center; gap:4px; font-size: 9pt; font-weight:800; padding:2px 8px; border-radius:4px; background:var(--red); color:#fff; margin-bottom:4px; }
