    .wl-act-time { color:var(--txt-muted); font-size: 9pt; margin-left:6px; font-family:inherit; }
    .wl-act-desc { color:var(--txt-2); font-size: 9pt; margin-top:2px; }
    .wl-act-scroll { max-height:300px; overflow-y:auto; }
    .wl-err-card { background:var(--surface); border:1px solid var(--border); border-radius:10px; padding:16px 18px; }
    .wl-err-header { display:flex; align-items:center; justify-content:space-between; margin-bottom:14px; }
    .wl-err-title { color:var(--txt-1); font-size:14px; font-weight:600; display:flex; align-items:center; gap:8px; }
    .wl-err-sub { color:var(--txt-muted); font-size: 9pt; }
    .wl-err-badge { background:rgba(248,113,113,0.15); border:1px solid rgba(248,113,113,0.35); color:#FF0000; font-size: 9pt; font-weight:700; padding:3px 10px; border-radius:6px; letter-spacing:0.5px; }
    .wl-err-tbl { width:100%; border-collapse:collapse; }
    .wl-err-tbl th { color:var(--txt-muted); font-size: 9pt; font-weight:500; letter-spacing:1px; text-transform:uppercase; padding:6px 8px; text-align:left; border-bottom:1px solid var(--border); }
    .wl-err-tbl td { padding:10px 8px; border-bottom:1px solid var(--border-2); vertical-align:middle; }
    .wl-err-sev { font-size: 9pt; font-weight:700; padding:3px 10px; border-radius:4px; letter-spacing:0.5px; white-space:nowrap; }
    .wl-err-sev.critical { background:rgba(248,113,113,0.18); color:#FF0000; border:1px solid rgba(248,113,113,0.35); }
    .wl-err-sev.warning { background:rgba(251,146,60,0.18); color:#fb923c; border:1px solid rgba(251,146,60,0.35); }
    .wl-err-well { color:var(--txt-1); font-size:9pt; font-weight:600; font-family:var(--font-family-mono); }
    .wl-err-code { color:var(--txt-muted); font-size: 9pt; }
    .wl-err-status { font-size: 9pt; font-weight:600; padding:3px 10px; border-radius:4px; white-space:nowrap; }
    .wl-err-status.overdue { background:rgba(248,113,113,0.12); color:#FF0000; border:1px solid rgba(248,113,113,0.25); }
    .wl-err-status.pct { color:var(--green); font-weight:700; }
    .wl-err-status.pct-med { color:#FFC000; font-weight:700; }
    .wl-err-status.pct-low { color:#FF0000; font-weight:700; }
    html:not(.navbar-light) .wl-err-status.pct { color:#00B050; }
    html:not(.navbar-light) .wl-err-status.pct-med { color:#e8c47a; }
    .wl-detail-card { background:var(--surface); border:1px solid var(--border); border-radius:10px; padding:16px 18px; margin-top:10px; }
    .wl-detail-header { display:flex; align-items:center; justify-content:space-between; margin-bottom:14px; flex-wrap:wrap; }
    .wl-detail-title { color:var(--txt-1); font-size:14px; font-weight:600; display:flex; align-items:center; gap:8px; }
    .wl-detail-sub { color:var(--txt-muted); font-size: 9pt; }
    .wl-detail-sorts { display:flex; align-items:center; gap:6px; }
    .wl-sort-label { color:var(--txt-muted); font-size: 9pt; }
    .wl-sort-btn { font-size: 9pt; padding:4px 12px; border-radius:6px; border:1px solid var(--border); background:transparent; color:var(--txt-muted); cursor:pointer; font-family:inherit; transition:all 0.15s; }
    .wl-sort-btn:hover { color:var(--txt-1); }
    .wl-sort-btn.active { background:rgba(248,113,113,0.15); border-color:rgba(248,113,113,0.4); color:#FF0000; }
    .wl-detail-tbl { width:100%; border-collapse:collapse; }
    .wl-detail-tbl th { color:var(--txt-muted); font-size: 9pt; font-weight:500; letter-spacing:1px; text-transform:uppercase; padding:8px 8px; text-align:left; border-bottom:1px solid var(--border); white-space:nowrap; }
    .wl-detail-tbl td { padding:12px 8px; border-bottom:1px solid var(--border-2); vertical-align:middle; font-size:9pt; }
