    .wl-status-badge.critical { background:rgba(248,113,113,0.18); color:#FF0000; border:1px solid rgba(248,113,113,0.35); }
    .wl-status-badge.watch { background:rgba(234,179,8,0.15); color:#FFC000; border:1px solid rgba(234,179,8,0.3); }
    html:not(.navbar-light) .wl-status-badge.watch { background:rgba(232,196,122,0.15); color:#e8c47a; border-color:rgba(232,196,122,0.3); }
    .wl-delay { color:#FF0000; font-size:9pt; font-weight:600; }
