    /* Filter popup */
    .ag-filter-popup {
      position: fixed; z-index: 10000;
      background: var(--ag-row-bg);
      border: 1px solid var(--ag-outer-border);
      border-radius: 6px;
      box-shadow: 0 6px 20px rgba(0,0,0,0.3);
      padding: 8px;
      min-width: 180px;
      font-family: var(--ag-font);
    }
    .ag-filter-popup input {
      width: 100%; padding: 6px 8px;
      font-family: inherit; font-size: 9pt;
      background: transparent;
      border: 1px solid var(--ag-col-border);
      border-radius: 4px;
      color: var(--ag-row-fg);
      outline: none;
    }
    .ag-filter-popup input:focus {
      border-color: #8b5cf6;
      box-shadow: 0 0 0 2px rgba(139,92,246,0.2);
    }
    .ag-filter-popup .ag-filter-clear {
      margin-top: 6px; width: 100%;
      padding: 5px 8px; font-size: 9pt;
      background: transparent;
      border: 1px solid var(--ag-col-border);
      border-radius: 4px;
      color: var(--ag-row-fg);
      cursor: pointer;
      font-family: inherit;
    }
