    .aia-test-sub { font-size: 9pt; color:var(--txt-muted); margin-top:3px; }
    .aia-test-body { padding:14px 18px; overflow-y:auto; flex:1; }
    .aia-test-input-block { margin-bottom:10px; }
    .aia-test-run-btn {
      width:100%; padding:9px 14px; margin-top:6px;
      background:#29378d;
      color:#fff; border:none; border-radius:8px;
      font-size:9pt; font-weight:600; cursor:pointer;
      display:flex; align-items:center; justify-content:center; gap:6px;
      transition:all 0.15s; font-family:var(--font-family);
    }
    .aia-test-run-btn:hover { transform:translateY(-1px); box-shadow:0 6px 16px rgba(41,55,141,0.3); }
    .aia-test-run-btn:disabled { opacity:0.6; cursor:wait; transform:none; box-shadow:none; }
    .aia-test-run-btn svg { width:13px; height:13px; stroke:currentColor; fill:none; stroke-width:2.4; }

    /* Trace */
    .aia-trace { margin-top:14px; }
    .aia-trace-title {
      font-size: 9pt; letter-spacing:1px; text-transform:uppercase;
      font-weight:700; color:var(--txt-2); margin-bottom:8px;
      display:flex; align-items:center; justify-content:space-between;
    }
    .aia-trace-title a { color:var(--accent); cursor:pointer; font-size: 9pt; letter-spacing:0; text-transform:none; font-weight:500; }
    .aia-trace-step {
      display:flex; gap:9px; padding:7px 0;
      font-size: 9pt; line-height:1.5;
      border-left:2px solid rgba(41,55,141,0.2);
      padding-left:11px; margin-left:6px;
      animation:aiaTraceIn 0.25s ease-out;
    }
    @keyframes aiaTraceIn { from { opacity:0; transform:translateX(-4px); } to { opacity:1; transform:translateX(0); } }
    .aia-trace-step.nested { margin-left:22px; border-left-color:rgba(31, 56, 100,0.3); }
    .aia-trace-step.thinking { color:var(--txt-muted); font-style:italic; }
    .aia-trace-step.tool-call { color:var(--accent); }
    .aia-trace-step.tool-result { color:var(--green); }
    .aia-trace-step.agent-call { color:#29378d; font-weight:500; }
    .aia-trace-step.final { color:var(--txt-1); font-weight:500; }
    .aia-trace-step.error { color:var(--red); }
    .aia-trace-time {
      font-family:var(--font-family-mono); font-size: 9pt;
      color:var(--txt-muted); flex-shrink:0; min-width:50px;
    }
    .aia-trace-msg { flex:1; min-width:0; word-wrap:break-word; }
    .aia-trace-msg code {
      background:rgba(41,55,141,0.08); padding:1px 5px; border-radius:3px;
      font-family:var(--font-family-mono); font-size: 9pt; color:#29378d;
    }
    .aia-trace-result-card {
      margin-top:10px; padding:10px 12px;
      background:var(--green-soft); border:1px solid var(--green-bd); border-radius:7px;
      font-size: 9pt; color:var(--txt-1);
    }
    .aia-trace-result-card.fail { background:var(--red-soft); border-color:var(--red-bd); }
    .aia-trace-result-card pre {
      font-family:var(--font-family-mono); font-size: 9pt;
      margin:6px 0 0; white-space:pre-wrap; word-wrap:break-word;
      color:var(--txt-2);
    }

    /* Tool picker mini-modal (reuse fd-modal-backdrop) */
    .aia-picker-tabs {
      display:flex; gap:0; padding:0 20px;
      border-bottom:1px solid var(--border); flex-shrink:0;
    }
    .aia-picker-tab {
      padding:10px 14px; font-size:9pt; font-weight:500;
      color:var(--txt-2); background:transparent; border:none; cursor:pointer;
      border-bottom:2px solid transparent;
      display:inline-flex; align-items:center; gap:6px;
      font-family:var(--font-family); transition:all 0.12s;
    }
    .aia-picker-tab:hover { color:var(--txt-1); }
    .aia-picker-tab.active { color:#29378d; border-bottom-color:#29378d; font-weight:600; }
    .aia-picker-tab svg { width:13px; height:13px; stroke:currentColor; fill:none; stroke-width:2; }
    .aia-picker-pane { display:none; }
    .aia-picker-pane.active { display:block; }

    /* â”€â”€â”€ Live Publish Progress Modal â”€â”€â”€ */
    .fd-pub-modal-body {
      padding:24px 28px; max-height:60vh; overflow-y:auto;
      background:linear-gradient(180deg, var(--surface-2), var(--surface));
    }
    .fd-pub-step {
      display:flex; align-items:flex-start; gap:14px;
      padding:12px 14px; margin:8px 0;
      background:var(--surface); border:1px solid var(--border-2);
      border-radius:9px;
      animation:fdPubStepIn 0.25s ease-out;
    }
    @keyframes fdPubStepIn { from { opacity:0; transform:translateX(-6px); } to { opacity:1; transform:translateX(0); } }
    .fd-pub-step.live { border-color:#FF0000; background:linear-gradient(135deg, rgba(255,0,0,0.04), var(--surface)); }
    .fd-pub-step.uiauto { border-color:#00B0F0; background:linear-gradient(135deg, rgba(13,148,136,0.05), var(--surface)); }
    .fd-pub-step.uiauto.success .fd-pub-step-icon { background:rgba(13,148,136,0.15); color:#00B0F0; }
    .fd-pub-step-icon {
      width:30px; height:30px; flex-shrink:0; border-radius:7px;
      display:flex; align-items:center; justify-content:center;
      background:var(--surface-2); color:var(--txt-muted);
    }
    .fd-pub-step-icon svg { width:14px; height:14px; stroke:currentColor; fill:none; stroke-width:2; stroke-linecap:round; stroke-linejoin:round; }
    .fd-pub-step.pending .fd-pub-step-icon { background:rgba(255,192,0,0.12); color:var(--amber); }
    .fd-pub-step.pending .fd-pub-step-icon svg { animation:fdSpin 1s linear infinite; }
    @keyframes fdSpin { from { transform:rotate(0); } to { transform:rotate(360deg); } }
    .fd-pub-step.success .fd-pub-step-icon { background:var(--green-soft); color:var(--green); }
    .fd-pub-step.error   .fd-pub-step-icon { background:var(--red-soft); color:var(--red); }
    .fd-pub-step-info { flex:1; min-width:0; }
    .fd-pub-step-name { font-size:10pt; font-weight:600; color:var(--txt-1); }
    .fd-pub-step-detail { font-size: 9pt; color:var(--txt-2); margin-top:3px; line-height:1.5; }
    .fd-pub-step-detail code { background:rgba(41,55,141,0.08); padding:1px 5px; border-radius:3px; font-family:var(--font-family-mono); font-size: 9pt; }
    .fd-pub-step-meta { font-family:var(--font-family-mono); font-size: 9pt; color:var(--txt-muted); margin-top:5px; word-break:break-all; }
    .fd-pub-live-tag {
      display:inline-flex; align-items:center; gap:4px;
      padding:1px 7px; border-radius:10px;
      background:rgba(255,0,0,0.1); color:#FF0000;
      border:1px solid rgba(255,0,0,0.3);
      font-size: 9pt; font-weight:700; letter-spacing:0.5px;
      margin-left:8px;
    }
    .fd-pub-live-tag::before { content:''; width:5px; height:5px; border-radius:50%; background:#FF0000; animation:fdLivePulse 1.4s infinite; }
    @keyframes fdLivePulse { 0%,100% { opacity:1; } 50% { opacity:0.3; } }

    .fd-pub-uiauto-tag {
      display:inline-flex; align-items:center; gap:4px;
      padding:1px 7px; border-radius:10px;
      background:rgba(13,148,136,0.1); color:#00B0F0;
      border:1px solid rgba(13,148,136,0.3);
      font-size: 9pt; font-weight:700; letter-spacing:0.5px;
      margin-left:8px;
    }
    .fd-pub-uiauto-tag::before { content:''; width:5px; height:5px; border-radius:50%; background:#10b981; animation:fdLivePulse 1.4s infinite; }

    /* UI automation result card */
    .fd-pub-uiauto-card {
      margin-top:14px; padding:14px 16px;
      background:linear-gradient(135deg, rgba(13,148,136,0.06), rgba(13,148,136,0.01));
      border:1.5px solid rgba(13,148,136,0.4); border-radius:9px;
    }
    .fd-pub-uiauto-head {
      display:flex; align-items:center; gap:9px; margin-bottom:8px;
      font-size:13px; font-weight:600; color:#00B0F0;
    }
    .fd-pub-uiauto-actions {
      display:flex; gap:8px; margin-top:10px; flex-wrap:wrap;
    }
    .fd-pub-uiauto-btn {
      display:inline-flex; align-items:center; gap:5px;
      padding:7px 12px; font-size: 9pt; font-weight:600;
      border-radius:6px; cursor:pointer; font-family:inherit;
      transition:all 0.15s;
