    .fd-pub-uiauto-btn.secondary:hover { background:var(--surface-2); }
    .fd-pub-uiauto-btn svg { width:12px; height:12px; stroke:currentColor; fill:none; stroke-width:2; }

    /* Script viewer (tabbed) */
    .fd-script-viewer {
      margin-top:12px;
      background:#0f172a; border-radius:8px; overflow:hidden;
      border:1px solid #1e293b;
    }
    .fd-script-tabs {
      display:flex; background:#1e293b; padding:0 8px;
      border-bottom:1px solid #334155;
    }
    .fd-script-tab {
      padding:8px 14px; font-size: 9pt; font-weight:600;
      color:#A5A5A5; background:transparent; border:none; cursor:pointer;
      border-bottom:2px solid transparent;
      display:inline-flex; align-items:center; gap:5px;
      font-family:inherit; transition:all 0.12s;
    }
    .fd-script-tab:hover { color:#e2e8f0; }
    .fd-script-tab.active { color:#10b981; border-bottom-color:#10b981; }
    .fd-script-tab svg { width:11px; height:11px; stroke:currentColor; fill:none; stroke-width:2; }
    .fd-script-actions {
      margin-left:auto; display:flex; align-items:center; gap:6px; padding:5px 8px 5px 0;
    }
    .fd-script-copy {
      padding:4px 9px; font-size: 9pt; font-weight:500;
      background:rgba(255,255,255,0.06); color:#cbd5e1;
      border:1px solid rgba(255,255,255,0.1); border-radius:5px;
      cursor:pointer; font-family:inherit;
      display:inline-flex; align-items:center; gap:4px;
      transition:all 0.12s;
    }
    .fd-script-copy:hover { background:rgba(255,255,255,0.1); color:#fff; }
    .fd-script-copy.copied { background:rgba(16,185,129,0.15); color:#10b981; border-color:rgba(16,185,129,0.4); }
    .fd-script-copy svg { width:11px; height:11px; stroke:currentColor; fill:none; stroke-width:2; }
    .fd-script-pane { display:none; }
    .fd-script-pane.active { display:block; }
    .fd-script-code {
      padding:14px 16px; max-height:340px; overflow:auto;
      font-family:var(--font-family-mono); font-size: 9pt;
      line-height:1.6; color:#e2e8f0;
      white-space:pre; tab-size:2;
    }
    .fd-script-code .kw   { color:#c084fc; }
    .fd-script-code .str  { color:#86efac; }
    .fd-script-code .com  { color:#7F7F7F; font-style:italic; }
    .fd-script-code .fn   { color:#60a5fa; }
    .fd-script-code .num  { color:#FFC000; }

    /* Pre-filled URL preview */
    .fd-pub-url-preview {
      margin-top:10px; padding:10px 12px;
      background:var(--surface-2); border:1px solid var(--border);
      border-radius:6px;
      font-family:var(--font-family-mono); font-size: 9pt;
      color:var(--txt-2); word-break:break-all; line-height:1.6;
    }
    .fd-pub-url-preview .url-key { color:var(--txt-muted); }
    .fd-pub-url-preview .url-val { color:var(--accent); }

    /* â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
       VISUAL BROWSER SIMULATOR â€” Watch Selenium drive Chrome
       Architectural note: real Selenium cannot run from inside
       a browser. This is a high-fidelity simulation that mirrors
       what driver.* calls produce visually. A console at the bottom
       /* shows the real commands; the simulator paints the result.
       â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• */
    .aut-overlay {
      position:fixed; inset:0;
      background:rgba(15,23,42,0.88);
      backdrop-filter:blur(8px); -webkit-backdrop-filter:blur(8px);
      z-index:10000;
      display:none; align-items:center; justify-content:center;
      animation:autFadeIn 0.3s ease;
    }
    .aut-overlay.open { display:flex; }
    @keyframes autFadeIn { from { opacity:0; } to { opacity:1; } }

    .aut-window {
      width:92vw; max-width:1140px;
      height:84vh; max-height:780px;
      background:#fff; border-radius:11px;
      box-shadow:0 30px 80px rgba(0,0,0,0.5);
      display:flex; flex-direction:column;
      overflow:hidden; position:relative;
      animation:autScaleIn 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
    }
    @keyframes autScaleIn { from { transform:scale(0.92); opacity:0; } to { transform:scale(1); opacity:1; } }

    .aut-chrome { background:#f1f3f4; border-bottom:1px solid #dadce0; padding:8px 12px 0; flex-shrink:0; }
    .aut-chrome-row1 { display:flex; align-items:center; gap:14px; margin-bottom:5px; padding-bottom:4px; }
    .aut-traffic { display:flex; gap:7px; padding-left:2px; }
    .aut-traffic-dot { width:12px; height:12px; border-radius:50%; }
    .aut-traffic-dot.r { background:#ff5f57; }
    .aut-traffic-dot.y { background:#febc2e; }
    .aut-traffic-dot.g { background:#28c840; }
    .aut-tabs { display:flex; flex:1; gap:4px; align-items:flex-end; }
    .aut-tab {
      background:#fff; border:1px solid #dadce0; border-bottom:none;
      border-radius:8px 8px 0 0; padding:7px 14px;
      font-size:9pt; color:#3c4043;
      display:flex; align-items:center; gap:8px;
      max-width:240px; font-family:-apple-system, sans-serif;
    }
    .aut-tab svg { width:13px; height:13px; }
    .aut-tab .ttl { white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
    .aut-tab.recording::after { content:''; width:7px; height:7px; border-radius:50%; background:#FF0000; animation:autPulse 1.4s infinite; flex-shrink:0; }
    @keyframes autPulse { 0%,100%{opacity:1;} 50%{opacity:0.3;} }

    .aut-chrome-row2 { display:flex; align-items:center; gap:6px; padding-bottom:8px; }
    .aut-nav-btn {
      width:30px; height:30px; background:transparent; border:none; cursor:default;
      color:#5f6368; border-radius:50%; display:flex; align-items:center; justify-content:center;
    }
    .aut-nav-btn svg { width:16px; height:16px; stroke:currentColor; fill:none; stroke-width:2; }

    .aut-url-bar {
      flex:1; background:#fff; border:1px solid #dadce0; border-radius:18px;
      padding:7px 16px; font-size:13px; color:#202124;
      display:flex; align-items:center; gap:10px;
      font-family:-apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    }
    .aut-url-bar svg { width:14px; height:14px; flex-shrink:0; color:#5f6368; }
    .aut-url-text { flex:1; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
    .aut-url-text .pro { color:#5f6368; }
    .aut-url-text .hst { color:#202124; font-weight:500; }
    .aut-url-text .pth { color:#5f6368; }

    .aut-control-badge {
      background:linear-gradient(135deg,#FF0000,#b91c1c); color:#fff;
      font-size: 9pt; font-weight:700; letter-spacing:0.6px;
      padding:5px 11px; border-radius:12px;
      display:flex; align-items:center; gap:6px; flex-shrink:0;
    }
    .aut-control-badge::before { content:''; width:6px; height:6px; border-radius:50%; background:#fff; animation:autPulse 1s infinite; }

    .aut-loading-bar { height:3px; background:transparent; position:relative; overflow:hidden; }
    .aut-loading-bar.active::after {
      content:''; position:absolute; top:0; left:-30%; bottom:0; width:30%;
      background:linear-gradient(90deg, transparent, #1a73e8, transparent);
      animation:autLoadingSlide 1.1s infinite linear;
    }
    @keyframes autLoadingSlide { from { left:-30%; } to { left:100%; } }

    .aut-viewport {
      flex:1; background:#fff; position:relative; overflow:auto;
      font-family:-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    }

    .aut-cursor {
      position:absolute; width:22px; height:22px; pointer-events:none;
      z-index:200; left:0; top:0;
      transition:top 0.7s cubic-bezier(0.45, 0, 0.15, 1), left 0.7s cubic-bezier(0.45, 0, 0.15, 1), opacity 0.3s;
      filter:drop-shadow(0 2px 4px rgba(0,0,0,0.35));
