/* â•â•â• Additional styles block 6 â•â•â• */
/* Activities page â€” uses 'act-' prefix */
        .act-kpi-strip { display:grid; grid-template-columns:repeat(5, 1fr); gap:12px; margin-bottom:14px; }
        .act-kpi {
          background:var(--surface); border:1px solid var(--border); border-radius:10px;
          padding:14px 16px; position:relative; overflow:hidden;
        }
        .act-kpi::before {
          content:''; position:absolute; top:0; left:0; bottom:0; width:3px;
          background:var(--accent);
        }
        .act-kpi.k-green::before  { background:#00B050; }
        .act-kpi.k-blue::before   { background:#29378d; }
        .act-kpi.k-amber::before  { background:#FFC000; }
        .act-kpi.k-red::before    { background:#FF0000; }
        .act-kpi.k-purple::before { background:#29378d; }
        .act-kpi-label { font-size: 9pt; color:var(--txt-muted); letter-spacing:0.6px; text-transform:uppercase; font-weight:700; }
        .act-kpi-val { font-size:24px; font-weight:700; color:var(--txt-1); margin-top:4px; line-height:1.1; }
        .act-kpi-val .small { font-size:13px; color:var(--txt-muted); font-weight:500; margin-left:3px; }
        .act-kpi-sub { font-size: 9pt; color:var(--txt-muted); margin-top:4px; }
        .act-kpi-bar { height:4px; background:var(--surface-2); border-radius:3px; margin-top:9px; overflow:hidden; }
        .act-kpi-bar-fill { height:100%; transition:width 0.4s; }

        .act-discipline-strip {
          display:grid; grid-template-columns:repeat(auto-fit, minmax(140px, 1fr)); gap:10px;
          margin-bottom:14px;
        }
        .act-disc-tile {
          background:var(--surface); border:1px solid var(--border); border-radius:8px;
          padding:11px 13px; display:flex; align-items:center; gap:10px;
          transition:all 0.12s; cursor:pointer;
        }
        .act-disc-tile:hover { border-color:var(--accent); transform:translateY(-1px); }
        .act-disc-icon {
          width:36px; height:36px; border-radius:8px; flex-shrink:0;
          display:flex; align-items:center; justify-content:center;
          font-family:var(--font-family-mono); font-size:14px; font-weight:700; color:#fff;
        }
        .act-disc-info { flex:1; min-width:0; }
        .act-disc-name { font-size:9pt; font-weight:600; color:var(--txt-1); }
        .act-disc-stats { font-size: 9pt; color:var(--txt-muted); margin-top:1px; font-family:var(--font-family-mono); }

        .act-grid-wrap {
          background:var(--surface); border:1px solid var(--border); border-radius:10px;
          padding:14px; margin-bottom:14px;
        }
        .act-grid-head { display:flex; align-items:center; gap:10px; margin-bottom:12px; padding-bottom:10px; border-bottom:1px solid var(--border-2); }
        .act-grid-title { font-size:13px; font-weight:600; color:var(--txt-1); flex:1; }
        .act-grid-sub { font-size: 9pt; color:var(--txt-muted); }
        .act-status-pill {
          display:inline-flex; align-items:center; gap:5px; padding:3px 9px;
          font-size: 9pt; font-weight:600; border-radius:11px;
          letter-spacing:0.2px; line-height:1; white-space:nowrap;
        }
        .act-status-pill::before { content:''; width:5px; height:5px; border-radius:50%; background:currentColor; }
        .act-status-pill.completed { background:rgba(0,176,80,0.1);  color:#00B050; border:1px solid rgba(0,176,80,0.25); }
        .act-status-pill.inprogress{ background:rgba(41,55,141,0.1);  color:#29378d; border:1px solid rgba(41,55,141,0.25); }
        .act-status-pill.notstarted{ background:rgba(127, 127, 127,0.1);color:#7F7F7F; border:1px solid rgba(127, 127, 127,0.25); }
        .act-status-pill.atrisk    { background:rgba(255,192,0,0.1);  color:#FFC000; border:1px solid rgba(255,192,0,0.25); }
        .act-status-pill.blocked   { background:rgba(255,0,0,0.1);  color:#FF0000; border:1px solid rgba(255,0,0,0.25); }

/* â•â•â• Additional styles block 7 â•â•â• */
.pen-body { padding: 18px 22px; }
        .pen-hero {
          display: grid; grid-template-columns: 1.8fr 1fr 1fr 1fr; gap: 12px;
          background: linear-gradient(135deg, rgba(255,0,0,0.06), rgba(255,0,0,0.02));
          border: 1px solid var(--red-bd); border-radius: 10px;
          padding: 16px 18px; margin-bottom: 16px;
        }
        .pen-hero-main { display: flex; flex-direction: column; gap: 4px; }
        .pen-hero-eyebrow {
          font-size: 9pt; font-weight: 700; letter-spacing: 1.2px;
          color: var(--red); text-transform: uppercase; display: flex; align-items: center; gap: 7px;
        }
        .pen-hero-eyebrow::before {
          content: ''; width: 7px; height: 7px; border-radius: 50%; background: var(--red);
          box-shadow: 0 0 0 3px rgba(255,0,0,0.18); animation: pen-pulse 1.8s infinite;
        }
        @keyframes pen-pulse { 0%,100%{opacity:1} 50%{opacity:0.35} }
        .pen-hero-title { font-size: 22px; font-weight: 700; color: var(--txt-1); letter-spacing: -0.3px; }
        .pen-hero-sub { font-size: 9pt; color: var(--txt-dim); margin-top: 2px; }
        .pen-hero-metric {
          border-left: 1px solid var(--border); padding-left: 14px;
          display: flex; flex-direction: column; justify-content: center;
        }
        .pen-hero-metric-lbl { font-size: 9pt; color: var(--txt-muted); font-weight: 600; letter-spacing: 0.5px; text-transform: uppercase; margin-bottom: 4px; }
        .pen-hero-metric-val { font-size: 20pt; font-weight: 700; letter-spacing: -0.3px; font-family: var(--font-family-mono); }
        .pen-hero-metric-val.red { color: var(--red); }
        .pen-hero-metric-val.amber { color: var(--amber); }
        .pen-hero-metric-sub { font-size: 9pt; color: var(--txt-muted); margin-top: 2px; }

        .pen-layout {
          display: grid; grid-template-columns: minmax(0, 1fr) 380px; gap: 14px; align-items: start;
        }
        @media (max-width: 1180px) { .pen-layout { grid-template-columns: 1fr; } }

        .pen-wells { display: flex; flex-direction: column; gap: 10px; }
        .pen-well-card {
          background: var(--surface); border: 1px solid var(--border); border-radius: 10px;
          overflow: hidden; transition: border-color 0.15s, box-shadow 0.15s;
        }
        .pen-well-card.selected {
          border-color: var(--red); box-shadow: 0 0 0 3px rgba(255,0,0,0.08);
        }
        .pen-well-head {
          padding: 14px 16px; display: grid;
          grid-template-columns: auto 1fr auto auto auto; gap: 14px; align-items: center;
          cursor: pointer;
        }
        .pen-well-head:hover { background: var(--surface-2); }
        .pen-well-sev {
          width: 4px; height: 38px; border-radius: 2px; background: var(--red);
        }
        .pen-well-sev.amber { background: var(--amber); }
        .pen-well-id {
          display: flex; flex-direction: column; gap: 3px;
        }
        .pen-well-name {
          font-size: 14px; font-weight: 700; color: var(--txt-1); font-family: var(--font-family-mono); letter-spacing: -0.2px;
        }
        .pen-well-cluster {
          font-size: 9pt; color: var(--txt-dim); display: flex; align-items: center; gap: 6px;
        }
        .pen-well-cluster .pen-chip {
          background: var(--surface-2); border: 1px solid var(--border);
          padding: 1px 7px; border-radius: 4px; font-size: 9pt; font-weight: 600;
          color: var(--txt-2); letter-spacing: 0.3px;
        }
        .pen-well-metric { display: flex; flex-direction: column; gap: 2px; text-align: right; }
        .pen-well-metric-lbl { font-size: 9pt; font-weight: 600; letter-spacing: 0.6px; color: var(--txt-muted); text-transform: uppercase; }
        .pen-well-metric-val { font-size: 14px; font-weight: 700; color: var(--txt-1); font-family: var(--font-family-mono); }
        .pen-well-metric-val.red { color: var(--red); }
        .pen-well-metric-val.amber { color: var(--amber); }
        .pen-well-expand {
          width: 28px; height: 28px; border-radius: 6px; background: var(--surface-2);
          display: grid; place-items: center; transition: transform 0.2s, background 0.15s;
          color: var(--txt-2); border: 1px solid var(--border);
        }
        .pen-well-card.selected .pen-well-expand { transform: rotate(180deg); background: var(--red-soft); color: var(--red); border-color: var(--red-bd); }

        .pen-well-body {
          display: none; border-top: 1px solid var(--border); padding: 16px 18px; background: var(--surface-2);
        }
        .pen-well-card.selected .pen-well-body { display: block; }

        .pen-detail-grid {
          display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-bottom: 14px;
        }
        @media (max-width: 820px) { .pen-detail-grid { grid-template-columns: 1fr; } }

        .pen-block {
          background: var(--surface); border: 1px solid var(--border); border-radius: 8px; padding: 12px 14px;
        }
        .pen-block-head {
          display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px;
        }
        .pen-block-title {
          font-size: 9pt; font-weight: 700; letter-spacing: 0.6px;
          color: var(--txt-2); text-transform: uppercase;
        }
        .pen-block-sub { font-size: 9pt; color: var(--txt-muted); font-family: var(--font-family-mono); }

        .pen-schedule-fill {
          height: 100%; background: linear-gradient(90deg, var(--blue), #93c5fd);
          border-radius: 5px 0 0 5px;
        }
        .pen-schedule-deadline {
          position: absolute; top: -3px; bottom: -3px; width: 2px; background: var(--red);
        }
        .pen-schedule-deadline::after {
          content: 'Deadline'; position: absolute; top: -14px; transform: translateX(-50%);
          font-size: 9pt; font-weight: 700; color: var(--red); letter-spacing: 0.3px;
        }
        .pen-schedule-labels {
          display: flex; justify-content: space-between; font-size: 9pt; color: var(--txt-dim); font-family: var(--font-family-mono);
        }

        .pen-risk-list { display: flex; flex-direction: column; gap: 8px; }
        .pen-risk-item {
          display: grid; grid-template-columns: 22px 1fr auto; gap: 10px;
          align-items: center; padding: 8px 0;
          border-bottom: 1px dashed var(--border-2);
        }
