        html:not(.navbar-light) .po-status.ok { background: rgba(74,222,128,0.12); color: #00B050; border-color: rgba(74,222,128,0.3); }
        html:not(.navbar-light) .po-status.warn { background: rgba(251,191,36,0.12); color: #FFC000; border-color: rgba(251,191,36,0.3); }
        html:not(.navbar-light) .po-status.crit { background: rgba(248,113,113,0.12); color: #FF0000; border-color: rgba(248,113,113,0.3); }
        html:not(.navbar-light) .po-status.done { background: rgba(45,212,191,0.12); color: #2dd4bf; border-color: rgba(45,212,191,0.3); }
        .po-status .dot { width: 5px; height: 5px; border-radius: 50%; background: currentColor; }

        .po-prog-cell {
          display: flex; align-items: center; gap: 8px;
          font-family: var(--font-family-mono); font-weight: 700;
          font-size: 9pt;
        }
        .po-prog-bar { width: 60px; height: 5px; background: var(--border); border-radius: 2px; overflow: hidden; flex-shrink: 0; }
        html:not(.navbar-light) .po-prog-bar { background: rgba(255,255,255,0.1); }
        .po-prog-fill { height: 100%; border-radius: 2px; }

        /* Right rail */
        .po-rail { display: flex; flex-direction: column; gap: 14px; }

        .po-mile-row {
          display: grid; grid-template-columns: 80px 1fr auto; gap: 10px;
          align-items: center;
          padding: 9px 18px; border-bottom: 1px solid var(--border-2);
          font-size: 9pt;
        }
        html:not(.navbar-light) .po-mile-row { border-bottom-color: rgba(255,255,255,0.04); }
        .po-mile-row:last-child { border-bottom: none; }
        .po-mile-date {
          font-family: var(--font-family-mono); font-size: 9pt; color: var(--txt-dim);
        }
        .po-mile-name {
          color: #29378d; font-weight: 500; font-size: 9pt;
          font-family: var(--font-family-mono);
          white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
        }
        html:not(.navbar-light) .po-mile-name { color: #60a5fa; }

        /* Activity feed */
        .po-act-row {
          display: grid; grid-template-columns: 24px 100px 1fr; gap: 10px;
          padding: 11px 18px; border-bottom: 1px solid var(--border-2);
          font-size: 9pt;
        }
        html:not(.navbar-light) .po-act-row { border-bottom-color: rgba(255,255,255,0.04); }
        .po-act-row:last-child { border-bottom: none; }
        .po-act-icon {
          width: 22px; height: 22px; border-radius: 50%;
          background: var(--blue-soft); color: var(--blue);
          display: grid; place-items: center;
          font-weight: 700; font-size: 9pt; flex-shrink: 0;
        }
        html:not(.navbar-light) .po-act-icon { background: rgba(96,165,250,0.15); color: #60a5fa; }
        .po-act-date {
          font-family: var(--font-family-mono);
          font-size: 9pt; color: var(--txt-dim); padding-top: 2px;
        }
        .po-act-comment { font-size: 9pt; color: var(--txt-2); line-height: 1.45; }
        .po-act-title { font-weight: 600; color: var(--txt-1); margin-bottom: 3px; }
        .po-act-meta { font-size: 9pt; color: var(--txt-muted); font-family: var(--font-family-mono); }
        .po-act-agent { color: var(--accent); }

        /* Delayed tasks */
        .po-del-row {
          display: grid; grid-template-columns: 24px 80px 1fr 60px; gap: 10px;
          align-items: center;
          padding: 9px 18px; border-bottom: 1px solid var(--border-2);
          font-size: 9pt;
        }
        html:not(.navbar-light) .po-del-row { border-bottom-color: rgba(255,255,255,0.04); }
        .po-del-row:last-child { border-bottom: none; }
        .po-del-icon {
          width: 22px; height: 22px; border-radius: 50%;
          background: var(--red-soft); color: var(--red);
          display: grid; place-items: center; flex-shrink: 0;
        }
        html:not(.navbar-light) .po-del-icon { background: rgba(248,113,113,0.15); color: #FF0000; }
        .po-del-date { font-family: var(--font-family-mono); font-size: 9pt; color: var(--txt-dim); }
        .po-del-name { color: var(--txt-2); font-weight: 500; line-height: 1.4; }
        .po-del-prog {
          font-family: var(--font-family-mono); font-weight: 700;
          font-size: 9pt; text-align: right; color: var(--red);
        }
        html:not(.navbar-light) .po-del-prog { color: #FF0000; }
