  font-size: 9pt;
}
.perf-matrix th, .perf-matrix td {
  padding:8px 10px;
  text-align:center;
  white-space:nowrap;
  border-bottom:1px solid var(--border);
  border-right:1px solid var(--border);
}
.perf-matrix th {
  font-weight:700;
  font-size: 9pt;
  letter-spacing:0.3px;
  background:var(--surface-2);
  color:var(--txt-1);
}
.perf-matrix .perf-corner {
  position:sticky; top:0; left:0;
  background:var(--surface-2);
  z-index:3;
  text-align:left;
  font-size: 9pt;
  color:var(--txt-muted);
  font-weight:700;
}
.perf-matrix .perf-col-head, .perf-matrix .perf-row-summary-head {
  position:sticky; top:0;
  background:var(--surface-2);
  z-index:2;
}
.perf-matrix .perf-row-head {
  position:sticky; left:0;
  background:var(--surface);
  z-index:1;
  text-align:left;
  font-family:var(--font-family-mono);
  font-weight:700;
  font-size: 9pt;
  color:var(--txt-1);
  min-width:180px;
}
.perf-cell {
  font-family:var(--font-family-mono);
  font-weight:700;
  font-size:9pt;
  cursor:pointer;
  transition:transform 0.12s ease, box-shadow 0.12s ease;
  min-width:90px;
}
.perf-cell:hover {
  transform:scale(1.04);
  box-shadow:0 2px 6px rgba(0,0,0,0.20);
  position:relative; z-index:2;
}
.perf-cell-empty {
  color:#A5A5A5;
  font-family:inherit;
  font-weight:400;
}
html:not(.navbar-light) .perf-cell-empty { color:rgba(255,255,255,0.20); }

/* Row/column summary cells */
.perf-row-summary, .perf-col-summary, .perf-corner-summary {
  font-family:var(--font-family-mono);
  font-weight:800;
  font-size:10pt;
  background:var(--surface-2);
  border-left:2px solid var(--border);
}
.perf-col-summary-row td {
  background:var(--surface-2);
  font-family:var(--font-family-mono);
  font-weight:800;
  border-top:2px solid var(--border);
}
.perf-col-summary-row .perf-row-head {
  font-weight:800;
  color:var(--txt-1);
}

/* Insights */
.perf-insights-card {
  background:var(--surface);
  border:1px solid var(--border);
  border-radius:10px;
  padding:14px;
}
.perf-insights-card .card-head { margin-bottom:10px; }
.perf-insights-list {
  display:flex; flex-direction:column; gap:14px;
}
.perf-insight-block {
  padding:12px 14px;
  border:1px solid var(--border);
  border-radius:8px;
  background:var(--surface-2);
}
.perf-insight-title {
  font-size:10pt;
  font-weight:700;
  letter-spacing:0.3px;
  margin-bottom:8px;
}
.perf-insight-good { color:#00B050; }
.perf-insight-bad  { color:#FF0000; }
.perf-insight-warn { color:#FFC000; }
.perf-insight-row {
  font-size:9pt;
  color:var(--txt-1);
  padding:4px 0;
  border-bottom:1px dashed var(--border);
}
.perf-insight-row:last-child { border-bottom:none; }
.perf-insight-pi {
  font-family:var(--font-family-mono);
  font-weight:800;
  margin-right:6px;
}
.perf-insight-meta {
  font-size: 9pt;
  color:var(--txt-muted);
  margin-left:6px;
}

