/* Modal overlay */
.wrpt-overlay {
  position:fixed; inset:0;
  background:rgba(8,12,28,0.60);
  z-index:99999;
  display:none;
  align-items:flex-start; justify-content:center;
  padding:24px 16px;
  overflow-y:auto;
  font-family: var(--font-family);
}
.wrpt-overlay.open { display:flex; }

/* -- Print / Export PDF � body.wrpt-printing is set by wellReportExport().
   The overlay is rendered deep inside <app-root>, so we can't just toggle
   display:none on body's direct children (that would hide its container).
   Instead we hide EVERY element via visibility:hidden, then re-show only
   the overlay subtree, then reposition the overlay to flow normally on the
   printed page. ----------------------------------------------------- */
@media print {
  body.wrpt-printing {
    background: #fff !important;
    overflow: visible !important;
  }
  /* Hide everything by default */
  body.wrpt-printing * {
    visibility: hidden !important;
    box-shadow: none !important;
  }
  /* Re-show only the report overlay and its descendants */
  body.wrpt-printing .wrpt-overlay,
  body.wrpt-printing .wrpt-overlay * {
    visibility: visible !important;
  }
  /* Reposition the overlay so it flows normally instead of as a fixed modal */
  body.wrpt-printing .wrpt-overlay {
    position: absolute !important;
    inset: 0 !important;
    top: 0 !important;
    left: 0 !important;
    width: 100% !important;
    height: auto !important;
    background: #fff !important;
    padding: 0 !important;
    margin: 0 !important;
    overflow: visible !important;
    display: block !important;
    z-index: auto !important;
  }
  body.wrpt-printing .wrpt-panel {
    max-width: 100% !important;
    width: 100% !important;
    border-radius: 0 !important;
    min-height: 0 !important;
    height: auto !important;
    background: #fff !important;
    overflow: visible !important;
  }
  /* Hide chrome that doesn't belong in the PDF */
  body.wrpt-printing .wrpt-head-actions,
  body.wrpt-printing .wrpt-head-actions *,
  body.wrpt-printing .wrpt-foot-actions,
  body.wrpt-printing .wrpt-foot-actions *,
  body.wrpt-printing .wrpt-icon-btn,
  body.wrpt-printing .wrpt-icon-btn *,
  body.wrpt-printing #wrptEmailDialog,
  body.wrpt-printing #wrptEmailDialog * {
    visibility: hidden !important;
    display: none !important;
  }
  body.wrpt-printing .wrpt-head {
    color: #1a202c !important;
    background: #fff !important;
    border-bottom: 1px solid #cbd5e0 !important;
  }
  /* Avoid splitting section cards across pages where possible */
  body.wrpt-printing .wrpt-section { page-break-inside: avoid; }
  @page { margin: 12mm; }
}
.wrpt-panel {
