   SPEECH â†’ ENGLISH TRANSLATOR MODAL
   â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• */

/* Backdrop */
.stt-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.55);
  backdrop-filter: blur(3px);
  z-index: 10100;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s;
}
.stt-backdrop.open {
  opacity: 1;
  pointer-events: all;
}

/* Modal container */
.stt-modal {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -46%) scale(0.96);
  width: min(780px, 94vw);
  background: #111827;
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.7);
  z-index: 10101;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s, transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}
.stt-modal.open {
  opacity: 1;
  pointer-events: all;
  transform: translate(-50%, -50%) scale(1);
}

/* Header */
.stt-header {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 20px 22px 18px;
  background: linear-gradient(135deg, #1F3864 0%, #ec4899 100%);
}
.stt-header-icon {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.18);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.stt-header-icon svg { width: 20px; height: 20px; }
.stt-header-text { flex: 1; min-width: 0; }
.stt-header-title {
  font-size: 14pt;
  font-weight: 700;
  color: #fff;
  line-height: 1.2;
}
.stt-header-sub {
  font-size: 9pt;
  color: rgba(255, 255, 255, 0.75);
  margin-top: 3px;
}
.stt-close-btn {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: none;
  background: rgba(255, 255, 255, 0.18);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: background 0.15s;
}
.stt-close-btn:hover { background: rgba(255, 255, 255, 0.3); }
.stt-close-btn svg { width: 15px; height: 15px; }

/* Controls row */
.stt-controls {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px 22px;
  background: #111827;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
}
.stt-record-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  font-size: 14px;
  font-weight: 700;
  color: #fff;
  background: linear-gradient(135deg, #1F3864, #ec4899);
  white-space: nowrap;
  flex-shrink: 0;
  transition: opacity 0.15s, transform 0.12s;
  font-family: inherit;
  box-shadow: 0 4px 14px rgba(31, 56, 100, 0.4);
}
.stt-record-btn:hover { opacity: 0.88; transform: translateY(-1px); }
.stt-record-btn.recording {
  background: linear-gradient(135deg, #FF0000, #f97316);
  box-shadow: 0 4px 14px rgba(255, 0, 0, 0.45);
  animation: sttPulse 1.2s ease-in-out infinite;
}
.stt-record-btn svg { width: 16px; height: 16px; }

@keyframes sttPulse {
  0%, 100% { box-shadow: 0 4px 14px rgba(255, 0, 0, 0.45); }
  50%       { box-shadow: 0 4px 24px rgba(255, 0, 0, 0.7); }
}

/* Waveform canvas */
.stt-waveform {
  flex: 1;
  height: 36px;
  display: flex;
  align-items: center;
}
.stt-waveform canvas {
  width: 100%;
  height: 36px;
  display: block;
}

/* Status badge */
.stt-status-badge {
  flex-shrink: 0;
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 9pt;
  font-weight: 700;
  background: rgba(255, 255, 255, 0.08);
  color: rgba(255, 255, 255, 0.5);
  border: 1px solid rgba(255, 255, 255, 0.12);
  letter-spacing: 0.3px;
}
.stt-status-badge.listening {
  background: rgba(255, 0, 0, 0.18);
  color: #FF0000;
  border-color: rgba(255, 0, 0, 0.35);
}
.stt-status-badge.processing {
  background: rgba(31, 56, 100, 0.18);
  color: #a5b4fc;
  border-color: rgba(31, 56, 100, 0.35);
}

/* Language detect row */
/* Language selector row */
.stt-lang-select-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 22px 4px;
}
.stt-lang-select-label {
  font-size: 9pt;
  font-weight: 600;
  letter-spacing: .07em;
  color: rgba(255,255,255,.5);
  text-transform: uppercase;
  white-space: nowrap;
}
.stt-lang-select {
  flex: 1;
  background: rgba(255,255,255,.07);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 8px;
  color: #e2e8f0;
  font-size: 13px;
  padding: 5px 10px;
  outline: none;
  cursor: pointer;
  appearance: auto;
  &:hover { border-color: rgba(31, 56, 100,.6); background: rgba(31, 56, 100,.12); }
  & option { background: #1e293b; color: #e2e8f0; }
}

.stt-lang-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 22px;
  background: #0f172a;
}
.stt-detected-badge {
  padding: 2px 8px;
  border-radius: 4px;
  background: #f97316;
  color: #fff;
  font-size: 9pt;
  font-weight: 800;
  letter-spacing: 0.8px;
}
.stt-detected-lang {
  font-size: 13px;
  font-weight: 700;
  color: #e2e8f0;
  flex: 1;
  letter-spacing: 0.4px;
}
.stt-clear-btn {
  padding: 4px 12px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.15);
  background: transparent;
  color: rgba(255, 255, 255, 0.5);
  font-size: 9pt;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  transition: background 0.15s, color 0.15s;
}
.stt-clear-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #e2e8f0;
}

/* Transcript area */
.stt-transcript-area {
  min-height: 160px;
  max-height: 220px;
  overflow-y: auto;
  padding: 0;
  background: #0d1421;
  scrollbar-width: thin;
  scrollbar-color: rgba(31, 56, 100, 0.3) transparent;
}
.stt-transcript-area::-webkit-scrollbar { width: 4px; }
.stt-transcript-area::-webkit-scrollbar-track { background: transparent; }
.stt-transcript-area::-webkit-scrollbar-thumb { background: rgba(31, 56, 100, 0.35); border-radius: 2px; }

.stt-transcript-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 160px;
  gap: 10px;
  color: rgba(255, 255, 255, 0.22);
  padding: 30px 20px;
}
.stt-transcript-placeholder svg {
  width: 38px;
  height: 38px;
  opacity: 0.3;
}
.stt-placeholder-title {
  font-size: 14px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.35);
}
.stt-placeholder-sub {
  font-size: 9pt;
  color: rgba(255, 255, 255, 0.2);
}

.stt-transcript-text {
  padding: 18px 22px;
  font-size: 15px;
  line-height: 1.7;
  color: #e2e8f0;
  white-space: pre-wrap;
  word-break: break-word;
}
.stt-transcript-text .stt-interim {
  color: rgba(226, 232, 240, 0.45);
  font-style: italic;
}

/* Footer */
.stt-footer {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 22px;
  background: #111827;
  border-top: 1px solid rgba(255, 255, 255, 0.07);
}
.stt-action-btn {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 8px 16px;
  border-radius: 8px;
  border: 1px solid rgba(31, 56, 100, 0.4);
  background: rgba(31, 56, 100, 0.12);
  color: #a5b4fc;
  font-size: 9pt;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  transition: background 0.15s, border-color 0.15s;
}
.stt-action-btn:hover {
  background: rgba(31, 56, 100, 0.22);
  border-color: rgba(31, 56, 100, 0.6);
  color: #c7d2fe;
}
.stt-action-btn svg { width: 13px; height: 13px; }
.stt-copy-btn {
  border-color: rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.05);
  color: rgba(255, 255, 255, 0.5);
}
.stt-copy-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: rgba(255, 255, 255, 0.25);
  color: #e2e8f0;
}

