/* ------------------------------------------------------------------
   Customise drawer — List/Tree view toggle + tree (Category → Dashboard → widgets)
   Shared by the Cluster Overview and ODC South drawers.
   ------------------------------------------------------------------ */
.cw-viewseg{display:inline-flex;background:#f1f5f9;border-radius:9px;padding:3px;margin-bottom:12px}
.cw-viewseg button{border:none;background:transparent;padding:6px 16px;border-radius:7px;font-size:12.5px;font-weight:600;color:#64748b;cursor:pointer;transition:background .15s,color .15s}
.cw-viewseg button.on{background:#fff;color:#123c69;box-shadow:0 1px 2px rgba(16,35,61,.12)}

.cw-tree{margin-top:2px}
.cw-tnode{display:flex;align-items:center;gap:8px;width:100%;text-align:left;border:none;background:transparent;cursor:pointer;border-radius:8px;padding:9px 10px;font:inherit;transition:background .12s}
.cw-tnode:hover{background:#f4f7fc}
.cw-tnode-lbl{font-weight:600;color:#16233d;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cw-tnode-meta{margin-left:auto;font-size:10.5px;color:#94a3b8;font-weight:600;flex:0 0 auto}
.cw-tnode--cat .cw-tnode-lbl{font-size:12px;text-transform:uppercase;letter-spacing:.05em;color:#0f2f57}
.cw-tnode--dash.is-active{background:#eef3fb}
.cw-tcaret{width:14px;height:14px;flex:0 0 14px;color:#94a3b8;transition:transform .15s}
.cw-tcaret.open{transform:rotate(90deg)}
.cw-tchildren{margin-left:14px;border-left:1px solid #e8edf4;padding-left:6px}
.cw-trow{display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:8px;transition:opacity .12s}
.cw-trow:hover{background:#f8fafc}
.cw-trow.cw-row--off{opacity:.55}
.cw-trow-info{min-width:0;display:flex;flex-direction:column;flex:1}

/* ------------------------------------------------------------------
   Chart AI Agent modal — global (was only in aiagents.component.scss,
   so the modal rendered unstyled on the dashboard builder page).
   ------------------------------------------------------------------ */
.db-ai-modal-body { padding: 18px 22px; }
.db-ai-prompt-area {
  width: 100%; padding: 11px 13px; min-height: 90px; resize: vertical;
  border: 1px solid var(--border, #e3e8ef); border-radius: 7px;
  background: var(--surface-2, #f8fafc); color: var(--txt-1, #16233d);
  font-size: 13px; font-family: inherit; line-height: 1.5; box-sizing: border-box;
}
.db-ai-prompt-area:focus { outline: none; border-color: #29378d; box-shadow: 0 0 0 3px rgba(41,55,141,.12); }
.db-ai-suggestions { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.db-ai-suggestion {
  padding: 5px 11px; font-size: 9pt; border-radius: 14px; background: rgba(41,55,141,.08);
  color: #29378d; border: 1px solid rgba(41,55,141,.25); cursor: pointer; transition: all .12s; font-family: inherit;
}
.db-ai-suggestion:hover { background: rgba(41,55,141,.15); }
.db-ai-trace {
  margin-top: 12px; padding: 10px 13px; background: #1e1e1e; border-radius: 7px;
  font-family: var(--font-family-mono, monospace); font-size: 9pt; color: #d4d4d4;
  max-height: 180px; overflow-y: auto; line-height: 1.6;
}
.db-ai-trace-line { animation: autTraceFadeIn .18s ease; }
.db-ai-trace-line.thinking { color: #dcdcaa; }
.db-ai-trace-line.tool { color: #9cdcfe; }
.db-ai-trace-line.ok { color: #4ec9b0; }
.db-ai-tag { font-size: 8.5px; font-weight: 800; letter-spacing: .04em; background: linear-gradient(90deg,#a855f7,#6366f1); color: #fff; padding: 1px 6px; border-radius: 7px; margin-left: 6px; }

/* Chart Library origin badges (Standard / AI generated / Custom) */
.db-origin { font-size: 8px; font-weight: 800; letter-spacing: .04em; text-transform: uppercase; padding: 1px 5px; border-radius: 5px; margin-left: 6px; vertical-align: middle; white-space: nowrap; }
.db-origin--std    { background: #eef2f7; color: #64748b; }
.db-origin--ai     { background: linear-gradient(90deg,#a855f7,#6366f1); color: #fff; }
.db-origin--custom { background: #e0f2fe; color: #0369a1; }

/* Custom Chart Builder modal — field grid */
.db-custom-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 6px; }
.db-custom-field { display: flex; flex-direction: column; gap: 5px; }
.db-custom-field.full { grid-column: 1 / -1; }
.db-custom-field select, .db-custom-field input {
  padding: 9px 11px; border: 1px solid var(--border, #e3e8ef); border-radius: 7px;
  background: var(--surface, #fff); color: var(--txt-1, #16233d); font: inherit; font-size: 13px; box-sizing: border-box;
}
.db-custom-field select:focus, .db-custom-field input:focus { outline: none; border-color: #29378d; box-shadow: 0 0 0 3px rgba(41,55,141,.12); }
@media (max-width: 560px) { .db-custom-grid { grid-template-columns: 1fr; } }

/* Custom Chart Builder — two-column editor (config + live preview) */
.db-custom-body { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
.db-custom-config { display: flex; flex-direction: column; gap: 12px; }
.db-viz-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.db-viz-tile {
  display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 12px 6px;
  border: 1px solid var(--border, #e3e8ef); border-radius: 9px; background: var(--surface, #fff);
  color: var(--txt-2, #64748b); cursor: pointer; font: inherit; font-size: 11px; font-weight: 600; transition: all .12s;
}
.db-viz-tile svg { width: 22px; height: 22px; }
.db-viz-tile:hover { border-color: #29378d; color: #29378d; }
.db-viz-tile.active { border-color: #29378d; background: rgba(41,55,141,.08); color: #29378d; box-shadow: inset 0 0 0 1px #29378d; }
.db-custom-preview { border: 1px solid var(--border, #e3e8ef); border-radius: 10px; background: var(--surface-2, #f8fafc); display: flex; flex-direction: column; overflow: hidden; }
.db-custom-preview-head { font-size: 10px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; color: var(--txt-2, #64748b); padding: 10px 14px; border-bottom: 1px solid var(--border, #e3e8ef); background: var(--surface, #fff); }
.db-custom-preview-body { position: relative; height: 340px; padding: 14px; }
.db-custom-preview-body canvas { display: block; }
.db-custom-pv-empty, .db-custom-kpi { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.db-custom-pv-empty { color: var(--txt-muted, #94a3b8); font-size: 12px; }
.db-custom-kpi-val { font-size: 52px; font-weight: 800; color: #29378d; line-height: 1; letter-spacing: -1px; }
.db-custom-kpi-lbl { font-size: 12px; font-weight: 600; color: var(--txt-2, #64748b); margin-top: 8px; text-align: center; }
.db-custom-tablewrap { position: absolute; inset: 14px; overflow: auto; }
.db-custom-tbl { width: 100%; border-collapse: collapse; font-size: 12px; }
.db-custom-tbl th { background: #1F3864; color: #fff; text-align: left; padding: 7px 10px; position: sticky; top: 0; }
.db-custom-tbl td { padding: 7px 10px; border-bottom: 1px solid var(--border, #e3e8ef); color: var(--txt-1, #16233d); }
@media (max-width: 720px) { .db-custom-body { grid-template-columns: 1fr; } .db-custom-preview-body { height: 260px; } }

/* ------------------------------------------------------------------
   Rendered widget content (KPI / table / list) — global so saved
   dashboards render proper tiles wherever they're viewed (BI Boards,
   dvs embed, etc.), not just inside the builder.
   ------------------------------------------------------------------ */
.db-w-kpi { text-align: center; padding: 14px 6px; }
.db-w-kpi-label { font-size: 9pt; font-weight: 600; letter-spacing: .5px; text-transform: uppercase; color: var(--txt-muted, #94a3b8); margin-bottom: 6px; }
.db-w-kpi-val { font-family: var(--font-family-mono, monospace); font-size: 24pt; font-weight: 700; color: var(--txt-1, #16233d); line-height: 1; }
.db-w-kpi-val.green { color: var(--green, #00B050); }
.db-w-kpi-val.red   { color: var(--red, #FF0000); }
.db-w-kpi-val.amber { color: var(--amber, #FFC000); }
.db-w-kpi-val.blue  { color: var(--accent, #29378d); }
.db-w-kpi-delta { font-size: 9pt; margin-top: 5px; color: var(--txt-muted, #94a3b8); }
.db-w-table { width: 100%; font-size: 9pt; border-collapse: collapse; }
.db-w-table th { font-size: 9pt; letter-spacing: .4px; text-transform: uppercase; color: var(--txt-muted, #94a3b8); padding: 5px 7px; text-align: left; border-bottom: 1px solid var(--border-2, #e3e8ef); }
.db-w-table td { padding: 5px 7px; border-bottom: 1px solid var(--border-2, #e3e8ef); color: var(--txt-1, #16233d); }
.db-w-table td.num { font-family: var(--font-family-mono, monospace); }
.db-w-list { padding: 0; margin: 0; list-style: none; }
.db-w-list-item { padding: 6px 0; font-size: 9pt; color: var(--txt-1, #16233d); border-bottom: 1px solid var(--border-2, #e3e8ef); display: flex; align-items: center; gap: 8px; }
.db-w-list-item:last-child { border-bottom: none; }
.db-w-list-item .ico { width: 18px; height: 18px; flex-shrink: 0; border-radius: 4px; display: flex; align-items: center; justify-content: center; font-size: 9pt; font-weight: 700; color: #fff; }

/* Widget drill-down affordances (builder canvas) */
.db-widget-act.db-drill-on { color: #2563eb; }
.db-widget-body--drill { position: relative; cursor: pointer; }
.db-widget-body--drill:hover { background: rgba(37,99,235,.04); }
.db-drill-hint { position: absolute; bottom: 6px; right: 10px; font-size: 8.5px; font-weight: 800; letter-spacing: .04em; text-transform: uppercase; color: #0369a1; background: #e0f2fe; padding: 2px 7px; border-radius: 6px; pointer-events: none; }

/* AG Grid — center-align column group / sub-group header labels (report engine).
   The label must fill the group cell, then its text span centers within it. */
.ag-header-group-cell .ag-header-group-cell-label {
  flex: 1 1 auto !important;
  width: 100% !important;
  justify-content: center !important;
}
.ag-header-group-cell .ag-header-group-cell-label .ag-header-group-text {
  flex: 1 1 auto !important;
  text-align: center !important;
}